  "inputs": {
    "brief": "Create a software to turn my Markdown notes into a searchable static site with tags and backlinks.\n",
    "capsule_draft_a": {"brief": "Create a software to turn my Markdown notes into a searchable static site with tags and backlinks.\n", "problem_statement": "Markdown notes are difficult to navigate and discover at scale; the user needs an automated way to publish notes as a static site with fast search, tag-based browsing, and backlinks between notes.", "goals": ["Ingest a folder (or repository) of Markdown notes and generate a static website from them.", "Provide full-text search across all notes in the generated static site.", "Support tags to categorize notes and enable browsing/filtering by tag.", "Detect and render backlinks (which notes link to the current note) and forward links between notes.", "Produce an output that can be hosted as static files (e.g., any static web host)."], "non_goals": ["Building a hosted SaaS service or requiring a server-side application at runtime.", "Real-time collaborative editing or multi-user permissions within the notes.", "A WYSIWYG note editor (authoring remains in Markdown).", "Guaranteeing compatibility with every Markdown extension or every wiki-link dialect without explicit specification.", "Mobile apps or desktop clients beyond the generated static site."], "constraints": [{"id": "CNS1", "type": "tech", "text": "Output must be a static site (no required server-side runtime for browsing/search/backlinks beyond what can run in the browser)."}], "assumptions": [{"id": "A1", "text": "Notes are available as Markdown files on a local filesystem or in a repository, and the tool can read them as input.", "impact": "high", "confidence": "medium", "needs_confirmation": true}, {"id": "A2", "text": "Backlinks can be derived from explicit links in the Markdown (e.g., standard Markdown links and/or a wiki-link format), and the chosen link syntax can be standardized for this project.", "impact": "high", "confidence": "low", "needs_confirmation": true}, {"id": "A3", "text": "Search is acceptable as an in-browser static search index (generated at build time and queried client-side).", "impact": "high", "confidence": "medium", "needs_confirmation": true}, {"id": "A4", "text": "Tags are expressed in a consistent, parseable way (e.g., frontmatter field, inline #tags, or both), to be defined during implementation.", "impact": "medium", "confidence": "low", "needs_confirmation": true}], "open_questions": [{"id": "Q1", "text": "What Markdown flavor and link syntax should be supported for internal links/backlinks (standard Markdown links, Obsidian-style [[WikiLinks]], both)?", "impact": "high", "blocking": true}, {"id": "Q2", "text": "How are tags represented in your notes (YAML frontmatter, inline #tags, a specific frontmatter key), and should nested tags be supported?", "impact": "high", "blocking": true}, {"id": "Q3", "text": "What is the expected scale (number of notes / total size) and performance target for search and page load?", "impact": "high", "blocking": false}, {"id": "Q4", "text": "What is the preferred build workflow (CLI tool, git-based build, watch mode during writing), and what OS environments must be supported?", "impact": "medium", "blocking": false}, {"id": "Q5", "text": "Do you need additional navigation features such as a graph view, note outline/TOC generation, or automatic index pages per tag?", "impact": "medium", "blocking": false}, {"id": "Q6", "text": "Where will the site be hosted (e.g., GitHub Pages, Netlify, local-only), and are there any restrictions on client-side JavaScript usage?", "impact": "medium", "blocking": false}], "success_metrics": ["SM1: Static site generation succeeds on a representative notes folder and produces a browsable site (manual verification: build completes without errors and output is static files).", "SM2: Search returns relevant results for a test set of queries (measurement: at least 90% of predefined queries return the expected note within top 10 results).", "SM3: Tags are correctly extracted and navigable (measurement: 100% of notes with tags appear under the corresponding tag pages/filters in a test dataset).", "SM4: Backlinks are correctly computed (measurement: for a test set of interlinked notes, 100% of expected backlinks appear on their target pages).", "SM5: Generated site is hostable as static files (measurement: deploy to a chosen static host or open from local file server and verify core features work without a backend)."], "stakeholders": ["Primary user (note author/maintainer)", "Readers of the published notes site (could be the same as the user)"], "glossary": [{"term": "Static site", "definition": "A website composed of pre-generated files (HTML/CSS/JS/assets) that can be served without server-side application logic."}, {"term": "Backlink", "definition": "A list of notes/pages that link to the current note/page, computed by analyzing links across the note set."}, {"term": "Tag", "definition": "A label associated with a note, used for categorization and navigation (representation to be specified)."}, {"term": "Full-text search", "definition": "Searching the contents of notes (not just titles), typically via an index generated at build time and queried client-side."}]},
    "capsule_draft_b": {"brief": "Create a software to turn my Markdown notes into a searchable static site with tags and backlinks.", "problem_statement": "User needs a way to convert personal Markdown notes into a browsable, searchable static website that supports tag-based organization and bidirectional linking between notes.", "goals": ["G1: Generate a static site from Markdown files that can be hosted without a backend server", "G2: Implement full-text search functionality across all notes", "G3: Support tag-based categorization and filtering of notes", "G4: Automatically detect and render backlinks between notes", "G5: Preserve Markdown formatting and structure in the generated site"], "non_goals": ["NG1: Real-time collaborative editing of notes", "NG2: Dynamic server-side rendering or database integration", "NG3: Mobile native applications", "NG4: Version control or history tracking of note changes", "NG5: Authentication or access control features"], "constraints": [{"id": "CNS1", "type": "tech", "text": "Output must be static HTML/CSS/JS that can be hosted on any web server or CDN"}, {"id": "CNS2", "type": "tech", "text": "Must process standard Markdown format as input"}], "assumptions": [{"id": "A1", "text": "User has Markdown notes stored locally in files", "impact": "high", "confidence": "high", "needs_confirmation": true}, {"id": "A2", "text": "Backlinks follow wiki-style [[note-name]] or similar syntax", "impact": "high", "confidence": "medium", "needs_confirmation": true}, {"id": "A3", "text": "Tags are embedded in Markdown files using a consistent format (e.g., frontmatter or inline #tags)", "impact": "high", "confidence": "medium", "needs_confirmation": true}, {"id": "A4", "text": "User wants to self-host or use static hosting (GitHub Pages, Netlify, etc.)", "impact": "medium", "confidence": "medium", "needs_confirmation": true}, {"id": "A5", "text": "Search can be client-side JavaScript-based rather than requiring a search server", "impact": "medium", "confidence": "high", "needs_confirmation": false}, {"id": "A6", "text": "User has basic command-line or build tool familiarity for running the generator", "impact": "low", "confidence": "medium", "needs_confirmation": true}], "open_questions": [{"id": "Q1", "text": "What specific Markdown flavor/extensions should be supported (CommonMark, GFM, etc.)?", "impact": "medium", "blocking": false}, {"id": "Q2", "text": "What is the expected scale (number of notes, total size)?", "impact": "medium", "blocking": false}, {"id": "Q3", "text": "What syntax should be used for backlinks and tags?", "impact": "high", "blocking": true}, {"id": "Q4", "text": "Should the site support themes or customizable styling?", "impact": "low", "blocking": false}, {"id": "Q5", "text": "Are there any specific search features required (fuzzy search, filters, sorting)?", "impact": "medium", "blocking": false}, {"id": "Q6", "text": "Should the tool watch for file changes and auto-regenerate, or run on-demand only?", "impact": "low", "blocking": false}, {"id": "Q7", "text": "What platforms/operating systems must be supported?", "impact": "medium", "blocking": false}], "success_metrics": ["SM1: Successfully generates static site from 100+ test Markdown files within 10 seconds", "SM2: Search returns relevant results within 200ms for typical queries", "SM3: All backlinks are correctly identified and rendered as clickable links", "SM4: Tag pages correctly aggregate all notes with each tag", "SM5: Generated site loads and functions in modern browsers (Chrome, Firefox, Safari, Edge) without errors"], "stakeholders": ["User (note author and primary end-user)", "Potential future users with similar note-taking workflows"], "glossary": [{"term": "Static Site", "definition": "A website consisting of fixed HTML, CSS, and JavaScript files that do not require server-side processing"}, {"term": "Backlink", "definition": "A bidirectional reference between notes, showing which other notes link to the current note"}, {"term": "Markdown", "definition": "A lightweight markup language with plain text formatting syntax"}, {"term": "Tag", "definition": "A keyword or label used to categorize and organize notes by topic or theme"}]}
  },
  "task": "Reconcile into a single Project Capsule.",
  "output_schema": {"$defs": {"Assumption": {"additionalProperties": false, "properties": {"id": {"title": "Id", "type": "string"}, "text": {"title": "Text", "type": "string"}, "impact": {"enum": ["low", "medium", "high"], "title": "Impact", "type": "string"}, "confidence": {"enum": ["low", "medium", "high"], "title": "Confidence", "type": "string"}, "needs_confirmation": {"title": "Needs Confirmation", "type": "boolean"}}, "required": ["id", "text", "impact", "confidence", "needs_confirmation"], "title": "Assumption", "type": "object"}, "Constraint": {"additionalProperties": false, "properties": {"id": {"title": "Id", "type": "string"}, "type": {"enum": ["time", "budget", "tech", "policy", "legal", "compliance", "org", "other"], "title": "Type", "type": "string"}, "text": {"title": "Text", "type": "string"}}, "required": ["id", "type", "text"], "title": "Constraint", "type": "object"}, "GlossaryItem": {"additionalProperties": false, "properties": {"term": {"title": "Term", "type": "string"}, "definition": {"title": "Definition", "type": "string"}}, "required": ["term", "definition"], "title": "GlossaryItem", "type": "object"}, "OpenQuestion": {"additionalProperties": false, "properties": {"id": {"title": "Id", "type": "string"}, "text": {"title": "Text", "type": "string"}, "impact": {"enum": ["low", "medium", "high"], "title": "Impact", "type": "string"}, "blocking": {"title": "Blocking", "type": "boolean"}}, "required": ["id", "text", "impact", "blocking"], "title": "OpenQuestion", "type": "object"}}, "additionalProperties": false, "properties": {"brief": {"title": "Brief", "type": "string"}, "problem_statement": {"title": "Problem Statement", "type": "string"}, "goals": {"items": {"type": "string"}, "title": "Goals", "type": "array"}, "non_goals": {"items": {"type": "string"}, "title": "Non Goals", "type": "array"}, "constraints": {"items": {"$ref": "#/$defs/Constraint"}, "title": "Constraints", "type": "array"}, "assumptions": {"items": {"$ref": "#/$defs/Assumption"}, "title": "Assumptions", "type": "array"}, "open_questions": {"items": {"$ref": "#/$defs/OpenQuestion"}, "title": "Open Questions", "type": "array"}, "success_metrics": {"items": {"type": "string"}, "title": "Success Metrics", "type": "array"}, "stakeholders": {"items": {"type": "string"}, "title": "Stakeholders", "type": "array"}, "glossary": {"items": {"$ref": "#/$defs/GlossaryItem"}, "title": "Glossary", "type": "array"}}, "required": ["brief", "problem_statement", "goals", "non_goals", "constraints", "assumptions", "open_questions", "success_metrics"], "title": "ProjectCapsulePayload", "type": "object"}
