{
  "schema_version": "1.0",
  "avenues_considered": [
    {
      "id": "avenue_ssg_existing",
      "summary": "Adopt an existing static site generator (e.g., Eleventy/Hugo/Astro) and add plugins/pipelines for tags, backlinks, and search."
    },
    {
      "id": "avenue_custom_generator",
      "summary": "Build a purpose-made Markdown-to-static-site generator focused on note-taking features (wikilinks, backlinks, graph, tag pages)."
    },
    {
      "id": "avenue_docs_framework",
      "summary": "Use a docs framework (e.g., Docusaurus/MkDocs) and extend it for wikilinks/backlinks and note-oriented navigation."
    },
    {
      "id": "avenue_client_side_app",
      "summary": "Generate mostly raw content and rely on a client-side app for navigation/search (SPA-like shell + prebuilt JSON index)."
    },
    {
      "id": "avenue_search_first",
      "summary": "Prioritize a strong search/indexing pipeline (FlexSearch/Lunr/Meilisearch-hosted) and keep page rendering simple."
    }
  ],
  "uncertainties": [
    {
      "id": "uncert_notes_scale",
      "summary": "Number of notes, average size, and total repository size (impacts build time, indexing strategy, and hosting constraints).",
      "impact": "high"
    },
    {
      "id": "unc_link_syntax",
      "summary": "Desired link syntax and resolution rules (e.g., [[wikilinks]] vs Markdown links, case sensitivity, path ambiguity, aliases).",
      "impact": "high"
    },
    {
      "id": "unc_markdown_flavor",
      "summary": "Markdown features needed (GFM tables, footnotes, math, mermaid, callouts) and how strictly to support Obsidian-style extensions.",
      "impact": "medium"
    },
    {
      "id": "unc_tags_source_of_truth",
      "summary": "How tags are defined (frontmatter, inline #tags, both) and normalization rules (hierarchical tags, casing, spaces).",
      "impact": "medium"
    },
    {
      "id": "unc_backlinks_scope",
      "summary": "What qualifies as a backlink (only explicit links, also mentions, headings/anchors, transclusions/embeds).",
      "impact": "medium"
    },
    {
      "id": "unc_search_requirements",
      "summary": "Search expectations (full-text vs title-only, fuzzy matching, highlighting, ranking, offline support, multi-language stemming).",
      "impact": "high"
    },
    {
      "id": "unc_url_structure",
      "summary": "Preferred URL scheme (based on file paths, slugs, note IDs) and long-term stability/redirect needs.",
      "impact": "medium"
    },
    {
      "id": "unc_hosting_target",
      "summary": "Hosting environment and constraints (GitHub Pages, Netlify, self-hosted; CI limits; need for zero server).",
      "impact": "medium"
    },
    {
      "id": "unc_incremental_builds",
      "summary": "Need for incremental builds/watch mode speed vs acceptable full rebuild times.",
      "impact": "medium"
    },
    {
      "id": "unc_assets_handling",
      "summary": "How to handle attachments (images/PDFs), relative paths, and link rewrites during build.",
      "impact": "medium"
    }
  ],
  "ambiguities": [
    "Whether notes are organized in folders that should map to site sections or whether navigation is primarily tag/backlink-driven.",
    "Whether to support multiple vaults/repos or a single notes directory.",
    "Whether to generate a backlinks panel per page, a global graph view, or both.",
    "Whether to support note aliases (multiple titles pointing to one note) and how to expose them.",
    "Whether to treat headings as linkable targets and how to generate stable heading anchors.",
