{
  "options": [
    {
      "id": "OPT_B_1",
      "summary": "A single, self-contained Command Line Interface (CLI) tool that orchestrates the entire process in-memory. It will parse Markdown files, compute backlinks, generate a search index, and render the final static HTML site in a single execution.",
      "components": [
        {
          "id": "CMP_B_1_1",
          "name": "CLI Application",
          "responsibilities": [
            "Handles user input (source/destination folders), orchestrates internal modules, and provides user feedback."
          ]
        },
        {
          "id": "CMP_B_1_2",
          "name": "Content Processor",
          "responsibilities": [
            "Reads Markdown files from the source directory.",
            "Parses content, extracts frontmatter, tags, and link information."
          ]
        },
        {
          "id": "CMP_B_1_3",
          "name": "Graph & Index Engine",
          "responsibilities": [
            "Builds a graph of all notes from parsed link information to compute backlinks.",
            "Generates a client-side full-text search index from note content."
          ]
        },
        {
          "id": "CMP_B_1_4",
          "name": "Site Renderer",
          "responsibilities": [
            "Converts processed content into final HTML pages using internal templates.",
            "Assembles the output directory with all generated HTML, CSS, client-side JS, and the search index."
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_B_1_1",
          "from": "CMP_B_1_2",
          "to": "CMP_B_1_3",
          "contract": "In-memory data structure containing all parsed notes, their metadata, and forward links."
        },
        {
          "id": "IF_B_1_2",
          "from": "CMP_B_1_3",
          "to": "CMP_B_1_4",
          "contract": "In-memory data structure enriched with backlink information and the generated search index data."
        }
      ],
      "tradeoffs": {
        "pros": [
          "Simple user experience with a single command to run.",
          "Potentially high performance due to in-memory processing, avoiding I/O overhead between stages.",
          "Easier dependency management as it's a single, cohesive application."
        ],
        "cons": [
          "Monolithic design can be harder to maintain and extend over time.",
          "Less flexibility to swap out individual parts like the Markdown parser or search library without code changes.",
          "All logic is tightly coupled within one codebase."
        ]
      },
      "risks": [
        "The monolithic codebase could become complex and difficult to refactor as new features are added.",
        "Performance may suffer at very large scale (e.g., >10,000 notes) if in-memory data structures become too large, leading to high memory consumption."
      ]
    },
    {
      "id": "OPT_B_2",
      "summary": "Leverage an existing extensible Static Site Generator (SSG) such as Eleventy. Core functionality like Markdown-to-HTML conversion and templating is handled by the SSG, while custom features like backlink generation and search indexing are implemented as plugins.",
      "components": [
        {
          "id": "CMP_B_2_1",
          "name": "Core SSG Engine (e.g., Eleventy)",
          "responsibilities": [
            "Provides the main build pipeline, including file watching, data loading, templating, and page generation.",
            "Provides a plugin API to extend its functionality."
          ]
        },
        {
          "id": "CMP_B_2_2",
          "name": "Data Preprocessor & Backlink Plugin",
          "responsibilities": [
            "Hooks into the SSG's build process to read all content.",
            "Builds a link graph across all notes and computes backlinks.",
            "Exposes the backlink data globally to the SSG's templating engine."
          ]
        },
        {
          "id": "CMP_B_2_3",
          "name": "Search Indexer Plugin",
          "responsibilities": [
            "Generates a client-side search index file (e.g., JSON) during the SSG build process.",
            "Places the generated index into the final site output directory."
          ]
        },
        {
          "id": "CMP_B_2_4",
          "name": "Frontend Search Module",
          "responsibilities": [
            "Client-side JavaScript that runs in the browser.",
            "Fetches the search index file and initializes a search library.",
            "Implements the search UI and displays results."
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_B_2_1",
          "from": "CMP_B_2_2",
          "to": "CMP_B_2_1",
          "contract": "Global data object provided via SSG plugin API, making note graph and backlink information accessible within templates."
        },
        {
          "id": "IF_B_2_2",
          "from": "CMP_B_2_3",
          "to": "CMP_B_2_4",
          "contract": "A static JSON search index file, generated during the build and fetched via an HTTP request by the client-side JavaScript in the browser."
        }
      ],
      "tradeoffs": {
        "pros": [
          "Significantly reduces development time by building on a mature, well-documented platform.",
          "Gains access to a large ecosystem of existing themes and plugins.",
          "Handles many common SSG problems out-of-the-box (e.g., live reload, asset pipelines)."
        ],
        "cons": [
          "Constrained by the architecture, limitations, and performance of the chosen SSG.",
          "Requires learning the specific plugin and data model of the SSG, which can have its own complexity.",
          "Adds a dependency on a large, external open-source project and its release cycle."
        ]
      },
      "risks": [
        "The chosen SSG may not provide the necessary hooks or flexibility to implement a specific feature, requiring complex workarounds.",
        "Future updates to the core SSG could introduce breaking changes in the plugin APIs, requiring maintenance work."
      ]
    },
    {
      "id": "OPT_B_3",
      "summary": "A pipeline of distinct, single-responsibility CLI tools that communicate via intermediate files in a standard data format (e.g., JSON). Each step (parsing, backlink analysis, indexing, rendering) is a separate, replaceable tool.",
      "components": [
        {
          "id": "CMP_B_3_1",
          "name": "Content Parser",
          "responsibilities": [
            "Scans a directory of Markdown files.",
            "Outputs a single structured JSON file containing the content, metadata, and extracted forward links for every note."
          ]
        },
        {
          "id": "CMP_B_3_2",
          "name": "Data Enricher",
          "responsibilities": [
            "Consumes the structured JSON from the Content Parser.",
            "Analyzes the link graph to compute backlinks for each note.",
            "Outputs an enriched version of the JSON with this new data."
          ]
        },
        {
          "id": "CMP_B_3_3",
          "name": "Search Indexer",
          "responsibilities": [
            "Consumes the structured JSON from the Content Parser.",
            "Generates a static client-side search index file."
          ]
        },
        {
          "id": "CMP_B_3_4",
          "name": "Site Renderer",
          "responsibilities": [
            "Consumes the enriched JSON from the Data Enricher.",
            "Applies templates to generate final HTML pages.",
            "Copies the generated pages, search index, and other static assets to the output directory."
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_B_3_1",
          "from": "CMP_B_3_1",
          "to": "CMP_B_3_2",
          "contract": "Primary structured data file (e.g., notes.json) on disk containing parsed content and forward links."
        },
        {
          "id": "IF_B_3_2",
          "from": "CMP_B_3_1",
          "to": "CMP_B_3_3",
          "contract": "Primary structured data file (e.g., notes.json) on disk containing parsed content and forward links."
        },
        {
          "id": "IF_B_3_3",
          "from": "CMP_B_3_2",
          "to": "CMP_B_3_4",
          "contract": "Enriched data file (e.g., enriched-notes.json) on disk containing backlink information."
        },
        {
          "id": "IF_B_3_4",
          "from": "CMP_B_3_3",
          "to": "CMP_B_3_4",
          "contract": "Generated search index file (e.g., search-index.json) on disk."
        }
      ],
      "tradeoffs": {
        "pros": [
          "Extremely flexible and modular; each component can be developed, tested, and replaced independently.",
          "Components are simple, single-purpose, and easier to reason about.",
          "Allows for mixing technologies (e.g., a parser in Rust, a renderer in Node.js)."
        ],
        "cons": [
          "More complex build orchestration is required (e.g., using a Makefile or shell script).",
          "Performance can be lower due to the I/O overhead of writing and reading intermediate files between each step.",
          "Maintaining the consistency of the intermediate JSON format across tools can be challenging."
        ]
      },
      "risks": [
        "The complexity of managing the multi-step build process could be a burden for the end-user compared to a single command.",
        "Changes to the intermediate JSON schema require careful coordination and updates across multiple independent tools."
      ]
    }
  ]
}

{
  "risk_register": [
    {
      "id": "RISK_A_1",
      "severity": "high",
      "description": "Link/backlink resolution errors due to ambiguous or mixed internal link syntax (e.g., Markdown links vs. WikiLinks), causing broken navigation and incorrect backlink lists.",
      "mitigation": {
        "text": "Specify supported link syntaxes (blocking decision) and implement a single canonical internal link model (normalized target IDs). Add fixture-based tests covering edge cases (relative paths, anchors, renamed files). Provide build warnings for unresolved links with source locations.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_2",
      "severity": "high",
      "description": "Tag extraction inconsistency (frontmatter vs inline tags; nested tags) leads to missing/incorrect tag pages and filtering results.",
      "mitigation": {
        "text": "Lock a tag specification (blocking decision) and implement a deterministic parser with precedence rules (e.g., frontmatter overrides inline). Add validation that reports invalid tag tokens and produces a summary tag inventory at build time.",
        "owner": "Product/Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_3",
      "severity": "critical",
      "description": "Client-side XSS or content injection vulnerabilities if Markdown/HTML is rendered unsafely (e.g., raw HTML passthrough, unsafe link protocols), compromising readers of the static site.",
      "mitigation": {
        "text": "Use a sanitizer/renderer configuration that disables raw HTML by default (or sanitizes it), blocks javascript: URLs, and enforces safe attributes. Add security tests with known XSS payloads. Document an explicit opt-in for trusted HTML if needed.",
        "owner": "Security/Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_4",
      "severity": "high",
      "description": "Search index quality/performance degradation at scale (slow queries, large JS payload, long build time) causing poor UX or unusable search on larger note sets.",
      "mitigation": {
        "text": "Define scale/performance targets (notes count, total MB). Choose an index approach suitable for in-browser search (tokenization, stemming optional). Implement incremental/optimized indexing, compression, and lazy loading of the index. Add benchmark fixtures and CI performance budgets.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_5",
      "severity": "medium",
      "description": "Slug/URL collisions (e.g., same filename in different folders, case-insensitive filesystems) cause pages to overwrite each other or links to resolve unpredictably.",
      "mitigation": {
        "text": "Define a deterministic slug strategy (include path segments or stable hashing). Detect collisions during build and fail with actionable errors unless an override map is provided.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_6",
      "severity": "high",
      "description": "Non-deterministic builds (ordering differences, locale/time-dependent formatting) produce noisy diffs and inconsistent site output across machines/CI.",
      "mitigation": {
        "text": "Make builds deterministic: stable sorting of inputs, fixed locale/timezone handling, content-hash-based asset naming, and pinned dependency versions. Add a reproducibility check comparing outputs across two clean runs.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_7",
      "severity": "medium",
      "description": "Markdown flavor/extension mismatch (CommonMark vs GFM vs custom) yields rendering differences and broken formatting relative to user expectations.",
      "mitigation": {
        "text": "Select and document a supported Markdown flavor and extensions. Add a conformance test pack with representative notes. Provide a compatibility matrix and a strict mode that flags unsupported syntax.",
        "owner": "Product/Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_8",
      "severity": "medium",
      "description": "File encoding and Unicode handling issues (non-UTF8, mixed line endings) cause build failures or corrupted output text/search results.",
      "mitigation": {
        "text": "Assume UTF-8 by default but detect/handle BOM and common encodings where feasible. Normalize line endings internally. Emit clear diagnostics identifying offending files and provide a preflight validation command.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_9",
      "severity": "high",
      "description": "Path traversal or unintended file inclusion during ingestion (e.g., following symlinks, reading outside the intended directory) leaks local files into the generated site.",
      "mitigation": {
        "text": "Constrain ingestion to a declared root directory, default to not following symlinks, and maintain an allowlist of file extensions. Add a safety check that rejects paths escaping the root and reports included files in a manifest.",
        "owner": "Security/Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_10",
      "severity": "medium",
      "description": "Backlink computation gaps for links with anchors, URL-encoded paths, or normalized titles lead to partially missing backlink lists.",
      "mitigation": {
        "text": "Normalize link targets consistently (decode, strip/standardize anchors, resolve relative paths) and store both page-level and section-level link relations. Add targeted tests for anchor links and encoded characters.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_11",
      "severity": "medium",
      "description": "Broken offline/local viewing due to browser security constraints (file:// restrictions) if the static site relies on fetch/XHR for the search index.",
      "mitigation": {
        "text": "Design search to work on static hosts and provide guidance for local preview (simple local server). Optionally support embedding the index into a JS bundle to avoid runtime fetch, or detect file:// and show instructions.",
        "owner": "Engineering/Docs",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_12",
      "severity": "medium",
      "description": "Asset pipeline issues (broken relative paths, missing CSS/JS, incorrect base URL) lead to a site that works locally but fails when deployed under a subpath (e.g., GitHub Pages project pages).",
      "mitigation": {
        "text": "Support configurable basePath and generate all links/assets relative to it. Add a deployment-mode test that builds with a non-root basePath and runs a simple link/asset check over the output.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_13",
      "severity": "medium",
      "description": "Excessive memory usage or timeouts on large repositories causes build failures in CI or on user machines.",
      "mitigation": {
        "text": "Stream where possible, avoid loading all contents at once, and implement incremental indexing and caching. Provide a performance troubleshooting guide and configurable limits (max file size, exclude globs).",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_14",
      "severity": "high",
      "description": "Incorrect incremental rebuild/watch behavior (if implemented) leads to stale search index/backlinks after edits, confusing users.",
      "mitigation": {
        "text": "If watch mode is offered, implement a dependency graph so edits trigger recomputation of affected pages, backlinks, and search index. Provide a 'full rebuild' fallback and add tests for edit/rename/delete scenarios.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_15",
      "severity": "low",
      "description": "Accessibility regressions (missing landmarks, poor contrast, non-keyboard navigable search UI) reduce usability for some readers.",
      "mitigation": {
        "text": "Adopt baseline accessibility guidelines for templates/components (semantic HTML, focus management, ARIA where needed). Add an accessibility checklist to review and at least one automated audit step during validation.",
        "owner": "Engineering/Design",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_16",
      "severity": "medium",
      "description": "Overly permissive configuration or plugin/theme extensibility (if added) introduces instability and makes outputs hard to support/reproduce.",
      "mitigation": {
        "text": "Keep the configuration surface minimal initially. Version configurations, validate schemas, and gate plugin execution behind explicit allowlists and warnings. Provide a safe default preset and a compatibility policy.",
        "owner": "Product/Engineering",
        "status": "planned"
      },
      "acceptance": null
    },
    {
      "id": "RISK_A_17",
      "severity": "medium",
      "description": "Information disclosure via generated artifacts (e.g., including draft/private notes, or embedding absolute filesystem paths in HTML/JS or search index).",
      "mitigation": {
        "text": "Support exclude patterns (globs) and a 'private' frontmatter flag. Ensure generated output never includes absolute source paths; use relative identifiers only. Emit a build manifest listing included sources for review.",
        "owner": "Engineering",
        "status": "planned"
      },
      "acceptance": null
    }
  ],
  "tool_policy": {
    "stage_policies": [
      {
        "stage": "Intake",
        "allowlisted_tools": [
          "artifact_read",
          "artifact_write"
        ],
        "restrictions": [
          {
            "tool": "artifact_read",
            "rule": "read_only",
            "notes": "Read only the provided project capsule and prior drafts; no external sources."
          },
          {
            "tool": "artifact_write",
            "rule": "write_required_outputs_only",
            "allowed_artifacts": [
              "audit_spine",
              "intake_notes"
            ],
            "notes": "Must be able to write audit spine/intake notes for traceability."
          }
        ],
        "hitl_triggers": [
          "Missing or contradictory scope inputs (e.g., undefined link/tag specification) that block downstream design choices.",
          "Any request to expand scope beyond static-site constraints."
        ]
      },
      {
        "stage": "Generate",
        "allowlisted_tools": [
          "artifact_read",
          "artifact_write"
        ],
        "restrictions": [
          {
            "tool": "artifact_write",
            "rule": "no_code_execution",
            "notes": "Generation is drafting/planning only; do not execute or claim execution."
          },
          {
            "tool": "artifact_write",
            "rule": "no_secrets",
            "notes": "Do not include credentials, tokens, or private paths in any artifacts."
          }
        ],
        "hitl_triggers": [
          "Proposed solution requires server-side runtime for search/backlinks (violates static constraint).",
          "Proposed content rendering enables unsafe HTML without sanitization."
        ]
      },
      {
        "stage": "Validate",
        "allowlisted_tools": [
          "artifact_read",
          "artifact_write"
        ],
        "restrictions": [
          {
            "tool": "artifact_write",
            "rule": "validation_outputs_only",
            "allowed_artifacts": [
              "validation_notes",
              "risk_checks"
            ],
            "notes": "Validation writes must be limited to checklists/findings, not major scope edits."
          }
        ],
        "hitl_triggers": [
          "Security-sensitive findings (e.g., XSS risk) without a concrete mitigation.",
          "Performance targets are missing while performance-sensitive features are specified."
        ]
      },
      {
        "stage": "Review",
        "allowlisted_tools": [
          "artifact_read",
          "artifact_write"
        ],
        "restrictions": [
          {
            "tool": "artifact_write",
            "rule": "write_required_outputs_only",
            "allowed_artifacts": [
              "review_findings",
              "audit_spine"
            ],
            "notes": "Review must be able to write findings and update audit spine."
          },
          {
            "tool": "artifact_write",
            "rule": "no_untracked_decisions",
