            "rule": "decision_record_only",
            "allowed_artifacts": [
              "governance_decision",
              "risk_acceptance_log"
            ],
            "notes": "Judge stage records accept/mitigate decisions; no new features introduced."
          }
        ],
        "hitl_triggers": [
