{
  "options": [
    {
      "id": "OPT_U_1",
      "summary": "Monolithic single-command CLI that runs an in-memory build pipeline end-to-end: read Markdown notes, extract metadata/tags/links, compute backlinks, build a client-side search index, and render a complete static HTML/CSS/JS site in one execution.",
      "components": [
        {
          "id": "CMP_U_1",
          "name": "CLI Entry Point / Orchestrator",
          "responsibilities": [
            "Parse command-line arguments (input folder, output folder, config file path)",
            "Orchestrate the build pipeline stages in sequence in a single run",
            "Report build progress and errors to stdout/stderr"
          ]
        },
        {
          "id": "CMP_U_2",
          "name": "Markdown Parser & Metadata Extractor",
          "responsibilities": [
            "Read all .md files from the input directory tree",
            "Parse YAML frontmatter to extract tags and metadata",
            "Parse Markdown into an AST and/or HTML-ready representation",
            "Detect and normalize internal links (standard Markdown links and optional wiki-links)"
          ]
        },
        {
          "id": "CMP_U_3",
          "name": "Graph (Links/Backlinks) Engine",
          "responsibilities": [
            "Build a forward-link graph from parsed internal links",
            "Compute backlinks for every note from the inverse graph",
            "Resolve link targets to output URLs",
            "Report broken/unresolvable links as warnings"
          ]
        },
        {
          "id": "CMP_U_4",
          "name": "Tag Index Builder",
          "responsibilities": [
            "Aggregate tags across all notes",
            "Generate per-tag note lists",
            "Produce a tag index structure for tag browsing pages"
          ]
        },
        {
          "id": "CMP_U_5",
          "name": "Search Index Generator",
          "responsibilities": [
            "Build a client-side full-text search index from note titles/content/tags at build time",
            "Serialize the index to a JSON (or equivalent) file included in the static output",
            "Apply basic index-size controls (e.g., stemming/stop words) as needed"
          ]
        },
        {
          "id": "CMP_U_6",
          "name": "HTML Renderer / Templating",
          "responsibilities": [
            "Convert Markdown/AST to HTML",
            "Inject backlinks, tag lists, and navigation into page templates",
            "Render tag index pages, home page, and search page",
            "Copy static assets (CSS, JS, images) to the output directory"
          ]
        },
        {
          "id": "CMP_U_7",
          "name": "Client-Side Search UI",
          "responsibilities": [
            "Load the pre-built search index in the browser",
            "Provide a search input with results rendering",
            "Optionally highlight matched terms in result snippets"
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_U_1",
          "from": "CMP_U_1",
          "to": "CMP_U_2",
          "contract": "Pass input directory path and config (Markdown flavor, link/tag syntax options) to the parser/extractor."
        },
        {
          "id": "IF_U_2",
          "from": "CMP_U_2",
          "to": "CMP_U_3",
          "contract": "Emit in-memory note records including slugs/titles/metadata and extracted forward links for link graph + backlink computation."
        },
        {
          "id": "IF_U_3",
          "from": "CMP_U_2",
          "to": "CMP_U_4",
          "contract": "Provide extracted tags per note (from frontmatter and/or inline tag syntax) for aggregation and tag page generation."
        },
        {
          "id": "IF_U_4",
          "from": "CMP_U_2",
          "to": "CMP_U_5",
          "contract": "Provide per-note indexable fields (slug, title, plain text content, tags) to build the search index artifact."
        },
        {
          "id": "IF_U_5",
          "from": "CMP_U_3",
          "to": "CMP_U_6",
          "contract": "Provide backlinks per note (e.g., Map<slug, BacklinkEntry[]>) for rendering on note pages."
        },
        {
          "id": "IF_U_6",
          "from": "CMP_U_4",
          "to": "CMP_U_6",
          "contract": "Provide tag index (e.g., Map<tag, slug[]>) for rendering tag pages and per-note tag navigation."
        },
        {
          "id": "IF_U_7",
          "from": "CMP_U_5",
          "to": "CMP_U_6",
          "contract": "Output a serialized search index file into the output assets and return its relative path for inclusion in the rendered site."
        },
        {
          "id": "IF_U_8",
          "from": "CMP_U_6",
          "to": "CMP_U_7",
          "contract": "Rendered search page references the search index asset and client-side JS bundle via static <script>/<link> tags."
        }
      ],
      "tradeoffs": {
        "pros": [
          "Simple single-process build; easy to reason about and debug",
          "Simple user experience: one command generates the whole site",
          "Potentially fast for small-to-medium note sets due to in-memory stage handoff",
          "Straightforward deployment: run CLI, upload output folder"
        ],
        "cons": [
          "Monolithic codebase can become harder to extend (themes, graph view, alternative search backends)",
          "Less flexibility to swap individual parts without code changes",
          "Often implies full rebuild on any change unless incremental build is explicitly implemented",
          "Client-side search index size can grow and impact first-load performance for large note sets"
        ]
      },
      "risks": [
        "Search index asset may become too large for very large note sets, degrading initial load time",
        "Memory usage can grow substantially at very large scale (e.g., many thousands of notes) due to in-memory representations",
        "Wiki-link and tag syntax ambiguity can cause incorrect extraction/resolution without a clear specification",
        "Single-threaded sequential build may become slow on very large repositories"
      ],
      "source_ids": [
        "OPT_A1",
        "OPT_B_1"
      ]
    },
    {
      "id": "OPT_U_2",
      "summary": "Custom plugin-based static site generator core with a formal build lifecycle and plugin API; each concern (file collection, Markdown parsing, backlinks, tags, search, theming) is a plugin, enabling swapping/extending behavior without modifying the core.",
      "components": [
        {
          "id": "CMP_U_8",
          "name": "Core Orchestrator & Plugin Host",
          "responsibilities": [
            "Load configuration and discover/register plugins",
            "Define and execute build lifecycle hooks (init, collectFiles, transform, resolve, render, finalize)",
            "Manage shared build context (note registry, site metadata, output paths)"
          ]
        },
        {
          "id": "CMP_U_9",
          "name": "File Collector Plugin",
          "responsibilities": [
            "Recursively scan input directory for Markdown files",
            "Emit file metadata into the shared note registry",
            "Support configurable file include/exclude patterns"
          ]
        },
        {
          "id": "CMP_U_10",
          "name": "Markdown Parser Plugin",
          "responsibilities": [
            "Parse each Markdown file into an AST (or equivalent)",
            "Extract YAML frontmatter",
            "Normalize internal link references into a canonical format"
          ]
        },
        {
          "id": "CMP_U_11",
          "name": "Backlink Resolver Plugin",
          "responsibilities": [
            "Build forward-link and backlink graphs from parsed link data",
            "Attach backlink metadata to each note in the shared registry"
          ]
        },
        {
          "id": "CMP_U_12",
          "name": "Tag Aggregator Plugin",
          "responsibilities": [
            "Collect tags from frontmatter and/or inline tag syntax",
            "Build tag-to-notes index",
            "Register tag index pages for rendering"
          ]
        },
        {
          "id": "CMP_U_13",
          "name": "Search Index Plugin",
          "responsibilities": [
            "Build a client-side search index and write index artifacts to the output directory",
            "Optionally support chunked/sharded index artifacts for larger sites"
          ]
        },
        {
          "id": "CMP_U_14",
          "name": "Theme / Renderer Plugin",
          "responsibilities": [
            "Provide HTML templates and CSS/JS assets",
            "Render note pages and index/tag/search pages using the shared build context",
            "Support theme switching via configuration"
          ]
        },
        {
          "id": "CMP_U_15",
          "name": "Client-Side Runtime",
          "responsibilities": [
            "Load and query the generated search index assets in the browser",
            "Render interactive search results and navigation UI elements",
            "Provide tag filter UI and backlink navigation"
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_U_9",
          "from": "CMP_U_8",
          "to": "CMP_U_9",
          "contract": "Hook: collectFiles(context) → context.noteRegistry populated with entries (filePath, slug)."
        },
        {
          "id": "IF_U_10",
          "from": "CMP_U_8",
          "to": "CMP_U_10",
          "contract": "Hook: transform(context) → each note enriched with (ast, frontmatter, rawLinks[])."
        },
        {
          "id": "IF_U_11",
          "from": "CMP_U_8",
          "to": "CMP_U_11",
          "contract": "Hook: resolve(context) → backlink map attached to context and/or notes."
        },
        {
          "id": "IF_U_12",
          "from": "CMP_U_8",
          "to": "CMP_U_12",
          "contract": "Hook: resolve(context) → tag index attached to context and tag pages registered for render."
        },
        {
          "id": "IF_U_13",
          "from": "CMP_U_8",
          "to": "CMP_U_13",
          "contract": "Hook: finalize(context) → search index artifacts written to output directory (optionally sharded)."
        },
        {
          "id": "IF_U_14",
          "from": "CMP_U_8",
          "to": "CMP_U_14",
          "contract": "Hook: render(context) → HTML files and static theme assets written to output directory using context data."
        },
        {
          "id": "IF_U_15",
          "from": "CMP_U_14",
          "to": "CMP_U_15",
          "contract": "Rendered pages reference client-side JS bundle and search index assets via relative static paths."
        }
      ],
      "tradeoffs": {
        "pros": [
          "Highly extensible: new features can be added as plugins without changing the core",
          "Clean separation of concerns, improving testability and maintainability",
          "Themes and search backends can be swapped via plugin selection/configuration",
          "Can evolve toward large-site needs (e.g., sharded search indexes) within a consistent lifecycle"
        ],
        "cons": [
          "More upfront design and implementation effort (plugin API, hook semantics, shared context schema)",
          "Plugin ordering and inter-plugin dependencies add complexity",
          "Debugging cross-plugin issues can be harder than a monolith",
          "Over-engineering risk for a small-scope initial release"
        ]
      },
      "risks": [
        "Plugin API may need multiple iterations to stabilize, delaying initial delivery",
        "Poorly specified plugin contracts can lead to brittle plugins and breaking changes",
        "Performance overhead or complexity from hook dispatch and large shared context objects may emerge at scale"
      ],
      "source_ids": [
        "OPT_A2"
      ]
    },
    {
      "id": "OPT_U_3",
      "summary": "Use an existing static site generator (SSG), specifically Eleventy/11ty, as the build engine; implement backlinks, tags, and search as Eleventy plugins/config, leveraging its templating, collections/data model, and watch/incremental build capabilities (with Pagefind for scalable client-side search).",
      "components": [
        {
          "id": "CMP_U_16",
          "name": "Eleventy (11ty) Core Engine",
          "responsibilities": [
            "Handle file discovery, templating, and static output generation",
            "Provide data cascade and collections APIs for structured content data",
            "Support watch mode and incremental rebuilds"
          ]
        },
        {
          "id": "CMP_U_17",
          "name": "Markdown Processing Configuration",
          "responsibilities": [
            "Configure Markdown library/flavor and parsing options",
            "Add wiki-link syntax support via Markdown plugin (if required)",
            "Extract frontmatter into Eleventy’s data model"
          ]
        },
        {
          "id": "CMP_U_18",
          "name": "Backlink Data Plugin (Eleventy Plugin)",
          "responsibilities": [
            "Scan collections/content for internal links",
            "Compute backlinks and inject backlink data into each note’s template data"
          ]
        },
        {
          "id": "CMP_U_19",
          "name": "Tag Collections & Tag Pages",
          "responsibilities": [
            "Use Eleventy’s tags/collections mechanisms to aggregate tags",
            "Generate per-tag index pages (e.g., via pagination templates)",
            "Provide tag lists/tag cloud data to templates"
          ]
        },
        {
          "id": "CMP_U_20",
          "name": "Search Index Build Step (Pagefind or equivalent)",
          "responsibilities": [
            "Generate a client-side full-text search index during/after the Eleventy build",
            "Index the rendered HTML output for accurate search over final content",
            "Write search assets into the output directory"
          ]
        },
        {
          "id": "CMP_U_21",
          "name": "Theme / Layout Templates",
          "responsibilities": [
            "Provide templates for note pages, tag pages, home, and search",
            "Include CSS and any client-side JS needed for navigation/backlinks/search integration",
            "Render backlink sections and tag links within templates"
          ]
        },
        {
          "id": "CMP_U_22",
          "name": "Client-Side Search UI (Pagefind UI or custom)",
          "responsibilities": [
            "Load chunked search index assets on demand",
            "Provide interactive search UI with highlighting",
            "Operate entirely client-side in the static site"
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_U_16",
          "from": "CMP_U_16",
          "to": "CMP_U_17",
          "contract": "Eleventy config registers Markdown processing (including wiki-link plugin if needed); .md files are processed through this configuration."
        },
        {
          "id": "IF_U_17",
          "from": "CMP_U_16",
          "to": "CMP_U_18",
          "contract": "Eleventy plugin hook/collection step receives all notes/collection items and can compute backlinks to inject into template data."
        },
        {
          "id": "IF_U_18",
          "from": "CMP_U_18",
          "to": "CMP_U_21",
          "contract": "Each note’s data object includes backlinks[] (e.g., {slug, title, excerpt/context}) available to templates."
        },
        {
          "id": "IF_U_19",
          "from": "CMP_U_16",
          "to": "CMP_U_19",
          "contract": "Tags/collections are populated from frontmatter tags (and/or derived tags) and made available to templates and pagination."
        },
        {
          "id": "IF_U_20",
          "from": "CMP_U_16",
          "to": "CMP_U_20",
          "contract": "AfterBuild (or equivalent) triggers search indexing against the built output directory."
        },
        {
          "id": "IF_U_21",
          "from": "CMP_U_20",
          "to": "CMP_U_22",
          "contract": "Search build step outputs static (often chunked) search assets; the search page includes references to these assets and UI JS."
        },
        {
          "id": "IF_U_22",
          "from": "CMP_U_21",
          "to": "CMP_U_16",
          "contract": "Templates are registered/configured in Eleventy and used to produce final static output files."
        }
      ],
      "tradeoffs": {
        "pros": [
          "Reduces custom code by leveraging a mature SSG for file handling and templating",
          "Watch mode and incremental builds available out of the box",
          "Pagefind-style search produces chunked indexes that scale better to thousands of pages",
          "Access to ecosystem of plugins/themes and community support"
        ],
        "cons": [
          "Constrained by the chosen SSG’s conventions, APIs, and upgrade cycle",
          "Backlink computation still requires custom integration with the SSG data model",
          "Less control over build pipeline internals than a fully custom generator",
          "Additional dependencies (SSG + plugins), and potentially a non-JS binary for search indexing"
        ]
      },
      "risks": [
        "SSG plugin/data model limitations may force workarounds for specific features",
        "Upgrades to the SSG or plugin APIs may introduce breaking changes requiring maintenance",
        "Search indexing toolchain (e.g., Pagefind) may add CI/CD complexity on some platforms",
        "Wiki-link resolution plugin may not cover all desired dialects/edge cases without customization"
      ],
      "source_ids": [
        "OPT_A3",
        "OPT_B_2"
      ]
    },
    {
      "id": "OPT_U_4",
      "summary": "Composable multi-tool pipeline: separate single-responsibility CLI tools (parser, backlink enricher, search indexer, renderer) communicate via intermediate on-disk artifacts (e.g., JSON), allowing independent development and replacement of stages while still producing a static site output.",
      "components": [
        {
          "id": "CMP_U_23",
          "name": "Content Parser (CLI)",
          "responsibilities": [
            "Scan a directory of Markdown files",
            "Output a structured data file (e.g., notes.json) containing content, metadata, tags, and extracted forward links for every note"
          ]
        },
        {
          "id": "CMP_U_24",
          "name": "Data Enricher (Backlinks) (CLI)",
          "responsibilities": [
            "Consume structured notes data from the parser",
            "Analyze the link graph to compute backlinks for each note",
            "Output an enriched structured data file including backlink information"
          ]
        },
        {
          "id": "CMP_U_25",
          "name": "Search Indexer (CLI)",
          "responsibilities": [
            "Consume structured notes data from the parser (or enriched data if desired)",
            "Generate a static client-side search index artifact (e.g., JSON files)"
          ]
        },
        {
          "id": "CMP_U_26",
          "name": "Site Renderer (CLI)",
          "responsibilities": [
            "Consume enriched structured data to generate final HTML pages using templates",
            "Copy generated pages, search index artifacts, and other static assets to the output directory"
          ]
        }
      ],
      "interfaces": [
        {
          "id": "IF_U_23",
          "from": "CMP_U_23",
          "to": "CMP_U_24",
          "contract": "On-disk structured data file (e.g., notes.json) containing parsed note content/metadata and extracted forward links."
        },
        {
          "id": "IF_U_24",
          "from": "CMP_U_23",
          "to": "CMP_U_25",
          "contract": "On-disk structured data file (e.g., notes.json) containing parsed note content/metadata and extracted forward links."
        },
        {
          "id": "IF_U_25",
          "from": "CMP_U_24",
          "to": "CMP_U_26",
          "contract": "On-disk enriched data file (e.g., enriched-notes.json) containing backlink information per note."
        },
        {
          "id": "IF_U_26",
          "from": "CMP_U_25",
          "to": "CMP_U_26",
          "contract": "On-disk search index artifact(s) (e.g., search-index.json and related files) to be copied/embedded into the final site output."
        }
      ],
      "tradeoffs": {
        "pros": [
          "High modularity: each stage can be developed, tested, and replaced independently",
          "Easier to mix technologies across stages (e.g., parser in one language, renderer in another)",
          "Clear intermediate artifact(s) can aid debugging and reproducibility"
        ],
        "cons": [
          "More complex build orchestration for the end-user compared to a single command",
          "I/O overhead from writing/reading intermediate files can reduce performance",
          "Intermediate schema/versioning must be maintained carefully across tools"
        ]
      },
      "risks": [
        "User experience may suffer if orchestration is cumbersome (multiple commands, ordering, cleanup)",
        "Intermediate JSON/schema changes require coordinated updates across multiple tools",
        "Disk usage can increase due to large intermediate artifacts on big note sets"
      ],
      "source_ids": [
        "OPT_B_3"
      ]
    }
  ],
