{
  "run_context": {"run_id": "33c8de04-c278-433f-a60c-ecde7f4a7db8", "stage": "repair.patch_generate", "timestamp": "2026-02-21T12:20:12.483934+00:00", "config": "council-os-hq"},
  "artifact_refs": {"capsule_draft_a": "capsule_draft_a_v1", "capsule_draft_b": "capsule_draft_b_v1", "capsule": "capsule_canonical_v1", "clarification_plan": "clarification_plan_v1", "requirements_draft_1": "requirements_draft_1_v1", "requirements_draft_2": "requirements_draft_2_v1", "architecture_draft_1": "architecture_draft_1_v1", "architecture_draft_2": "architecture_draft_2_v1", "qa_templates_draft_1": "qa_templates_draft_1_v1", "qa_templates_draft_2": "qa_templates_draft_2_v1", "risk_gov_draft_1": "risk_gov_draft_1_v1", "risk_gov_draft_2": "risk_gov_draft_2_v1", "requirements_merge": "requirements_merge_v1", "requirements_canonical": "requirements_canonical_v1", "architecture_merge": "architecture_merge_v1", "architecture_canonical": "architecture_canonical_v1", "risk_gov_merge": "risk_gov_merge_v1", "risk_gov_canonical": "risk_gov_canonical_v1", "qa_strategy_canonical": "qa_strategy_canonical_v1", "acceptance_draft": "acceptance_draft_v1", "acceptance_canonical": "acceptance_canonical_v1", "alignment_warnings": "alignment_warnings_v1", "branch_set": "branch_set_v1", "candidate_delta_B2B": "candidate_delta_B2B_v2", "candidate_delta_B2A": "candidate_delta_B2A_v1", "candidate_delta_B1B": "candidate_delta_B1B_v1", "candidate_delta_B1A": "candidate_delta_B1A_v1"},
  "inputs": {
    "candidate_ref": "plan_candidate_B2B_v2",
    "plan_candidate": {"candidate_id": "B2B", "branch_id": "B2", "synthesizer_id": "candidate_b_anthropic", "inputs": {"capsule_ref": "capsule_canonical_v1", "draft_refs": ["capsule_draft_a_v1", "capsule_draft_b_v1", "requirements_draft_1_v1", "requirements_draft_2_v1", "architecture_draft_1_v1", "architecture_draft_2_v1", "qa_templates_draft_1_v1", "qa_templates_draft_2_v1", "risk_gov_draft_1_v1", "risk_gov_draft_2_v1", "acceptance_draft_v1"], "branch_ref": "B2"}, "plan_package": {"meta": {"plan_id": "243599e8-0008-4fbb-a266-a217d2a78d92", "version": "v2", "plan_version": null, "created_at": "2026-02-21T12:17:19.701962+00:00", "source_run_id": "33c8de04-c278-433f-a60c-ecde7f4a7db8", "schema_version": "1.0.0", "candidate_id": "B2B", "branch_id": "B2", "plan_status": "CANDIDATE", "parent_plan_hash": null, "amendment_id": null, "hash_spec_version": null}, "project_capsule": {"brief": "Create a software to turn my Markdown notes into a searchable static site with tags and backlinks.\n", "problem_statement": "Markdown notes become difficult to navigate and discover at scale; the user needs an automated way to convert a set of Markdown files into a browsable static website with fast full-text search, tag-based browsing, and bidirectional linking/backlinks between notes.", "goals": ["G1: Ingest a folder (or repository) of Markdown notes and generate a static website from them.", "G2: Provide full-text search across all notes in the generated static site.", "G3: Support tags to categorize notes and enable browsing/filtering by tag.", "G4: Detect and render forward links and backlinks between notes.", "G5: Preserve Markdown formatting and structure in the generated site output."], "non_goals": ["NG1: Building a hosted SaaS service or requiring a server-side application/database at runtime.", "NG2: Real-time collaborative editing or multi-user permissions within the notes.", "NG3: A WYSIWYG note editor (authoring remains in Markdown).", "NG4: Mobile native applications or desktop clients beyond the generated static site.", "NG5: Authentication or access control features.", "NG6: Version control or history tracking of note changes.", "NG7: Guaranteeing compatibility with every Markdown extension or every wiki-link dialect without explicit specification."], "constraints": [{"id": "CNS1", "type": "tech", "text": "Output must be a static site (static HTML/CSS/JS/assets), with no required server-side runtime for browsing/search/backlinks beyond what can run in the browser."}, {"id": "CNS2", "type": "tech", "text": "Must process standard Markdown files as input (Markdown flavor/extensions to be specified)."}], "assumptions": [{"id": "A1", "text": "Notes are available as Markdown files on a local filesystem or in a repository, and the tool can read them as input.", "impact": "high", "confidence": "medium", "needs_confirmation": true}, {"id": "A2", "text": "Backlinks can be derived from explicit links in the Markdown (e.g., standard Markdown links and/or a wiki-link format), and the link syntax can be standardized/specified for this project.", "impact": "high", "confidence": "low", "needs_confirmation": true}, {"id": "A3", "text": "Search is acceptable as an in-browser (client-side) search index generated at build time and queried in the static site.", "impact": "high", "confidence": "high", "needs_confirmation": true}, {"id": "A4", "text": "Tags are expressed in a consistent, parseable way (e.g., YAML frontmatter field and/or inline #tags) that will be specified for the project.", "impact": "high", "confidence": "medium", "needs_confirmation": true}, {"id": "A5", "text": "The generated site will be hosted via static hosting (e.g., GitHub Pages/Netlify) or self-hosted without backend requirements.", "impact": "medium", "confidence": "medium", "needs_confirmation": true}, {"id": "A6", "text": "The user can run a CLI/build tool to generate the site.", "impact": "low", "confidence": "medium", "needs_confirmation": true}], "open_questions": [{"id": "Q1", "text": "What Markdown flavor and internal link syntax should be supported for links/backlinks (CommonMark/GFM; standard Markdown links, Obsidian-style [[WikiLinks]], both)?", "impact": "high", "blocking": true}, {"id": "Q2", "text": "How are tags represented in the notes (YAML frontmatter key, inline #tags, both), and should nested tags be supported?", "impact": "high", "blocking": true}, {"id": "Q3", "text": "What is the expected scale (number of notes/total size) and performance targets for search and page load?", "impact": "high", "blocking": false}, {"id": "Q4", "text": "What is the preferred build workflow (CLI, git-based build, watch mode) and what OS environments must be supported?", "impact": "medium", "blocking": false}, {"id": "Q5", "text": "Do you need additional navigation features such as a graph view, note outline/TOC generation, or automatic index pages per tag?", "impact": "medium", "blocking": false}, {"id": "Q6", "text": "Where will the site be hosted (e.g., GitHub Pages, Netlify, local-only), and are there any restrictions on client-side JavaScript usage?", "impact": "medium", "blocking": false}, {"id": "Q7", "text": "Should the site support themes or customizable styling?", "impact": "low", "blocking": false}, {"id": "Q8", "text": "Are there any specific search features required (e.g., fuzzy search, tag filters, sorting, highlighting)?", "impact": "medium", "blocking": false}], "success_metrics": ["SM1: Static site generation succeeds on a representative notes folder and produces a browsable site (manual verification: build completes without errors and output is static files).", "SM2: Search returns relevant results for a test set of queries (measurement: at least 90% of predefined queries return the expected note within top 10 results).", "SM3: Tags are correctly extracted and navigable (measurement: 100% of notes with tags appear under the corresponding tag pages/filters in a test dataset).", "SM4: Backlinks are correctly computed (measurement: for a test set of interlinked notes, 100% of expected backlinks appear on their target pages).", "SM5: Generated site is hostable as static files (measurement: deploy to a chosen static host or open from a local file server and verify core features work without a backend).", "SM6: Generated site loads and functions in modern browsers (Chrome, Firefox, Safari, Edge) without errors on a representative dataset.", "SM7: On a representative dataset (e.g., 100+ notes), generation time and search responsiveness meet agreed performance targets (targets to be defined once scale is known)."], "stakeholders": ["Primary user (note author/maintainer)", "Readers of the published notes site (could be the same as the user)", "Potential future users with similar note-taking workflows"], "glossary": [{"term": "Static site", "definition": "A website composed of pre-generated files (HTML/CSS/JS/assets) that can be served without server-side application logic."}, {"term": "Markdown", "definition": "A lightweight markup language used to format plain text documents."}, {"term": "Backlink", "definition": "A list of notes/pages that link to the current note/page, computed by analyzing links across the note set."}, {"term": "Tag", "definition": "A label associated with a note, used for categorization and navigation (representation to be specified)."}, {"term": "Full-text search", "definition": "Searching the contents of notes (not just titles), typically via an index generated at build time and queried client-side."}]}, "scope": null, "constraints": null, "executive_summary": "Candidate B2B implements a custom plugin-based static site generator (O2) with a hybrid milestone strategy. Milestone 1 (Big Bang) delivers the Core Orchestrator, plugin API, shared build context schema, and the File Collector and Markdown Parser plugins as a stable foundation. Milestone 2 (Thin Slice) layers on the Tag Aggregator, Backlink Resolver, Search Index, and Theme/Renderer plugins one at a time, each independently testable against the plugin contract. A final Milestone 3 performs end-to-end integration, cross-browser validation, performance benchmarking, and security hardening. This approach accepts higher upfront design cost in exchange for long-term extensibility, clean separation of concerns, and the ability to swap or upgrade individual plugins (e.g., search backend, theme) without rewriting the core. Governance posture is sandboxed tooling with high HITL strictness; blocking questions Q1 (link syntax) and Q2 (tag format) must be resolved before Milestone 2 begins.", "requirements": [{"id": "R1", "priority": "MUST", "text": "The system MUST accept a user-specified folder (or repository working directory) as input and recursively discover Markdown (.md) files to form the notes corpus.", "rationale": "Core workflow requires ingesting a directory of Markdown notes to generate the site."}, {"id": "R2", "priority": "MUST", "text": "The system MUST generate a static website output consisting only of static files (HTML/CSS/JS/assets) that can be hosted or viewed without any required server-side runtime for browsing, search, tags, or backlinks.", "rationale": "Static-only output is a hard constraint and aligns with the non-goal of requiring a backend at runtime."}, {"id": "R3", "priority": "MUST", "text": "The system MUST parse and render each input Markdown file into a corresponding static HTML page while preserving Markdown formatting and structure (e.g., headings, lists, code blocks, emphasis, links; and commonly used elements such as images and tables when supported by the selected flavor).", "rationale": "Readable output requires faithful Markdown-to-HTML rendering consistent with the project’s chosen Markdown flavor."}, {"id": "R4", "priority": "MUST", "text": "The system MUST produce one distinct, navigable page per input note, with each page having a stable URL derived deterministically from the note’s path/filename and/or a frontmatter-defined slug.", "rationale": "Stable per-note pages are necessary for browsing, deep linking, and consistent forward links/backlinks."}, {"id": "R5", "priority": "MUST", "text": "The system MUST build a client-side full-text search index at generation time and provide an in-browser search UI that searches across all note contents (and titles where available) without a server.", "rationale": "Full-text search is a primary goal and must operate entirely in the browser to satisfy the static-site constraint."}, {"id": "R6", "priority": "SHOULD", "text": "The search UI SHOULD display a results list including each matching note’s title (or filename) and a snippet and/or highlighted match context; selecting a result SHOULD navigate to the corresponding note page.", "rationale": "Improves search usability and supports practical discoverability at scale."}, {"id": "R7", "priority": "MUST", "text": "The system MUST extract tags from notes using a specified, consistent convention and expose tag-based browsing/filtering in the generated site.", "rationale": "Tags are a stated goal; consistent parsing is required for reliable tag navigation."}, {"id": "R8", "priority": "MUST", "text": "The generated site MUST provide a per-tag navigation experience such that each tag has a listing of all notes containing that tag (e.g., tag pages and/or tag filters).", "rationale": "Makes tags actionable for navigation and supports the tag browsing goal."}, {"id": "R9", "priority": "MUST", "text": "The system MUST detect forward links between notes based on a specified internal link syntax and render those links as clickable navigational elements in output pages.", "rationale": "Forward link rendering is required for cross-note navigation and is prerequisite for backlink computation."}, {"id": "R10", "priority": "MUST", "text": "The system MUST compute backlinks for each note by analyzing the corpus link graph and render a backlinks section on each note page listing all notes that link to it.", "rationale": "Backlinks are a core requirement and a key differentiator for navigability."}, {"id": "R11", "priority": "MUST", "text": "The system MUST be invocable as an offline build step via a command-line interface (CLI) that accepts at minimum an input directory path and an output directory path, and core generation MUST NOT require network access.", "rationale": "Aligns with the intended workflow (local build) and supports static hosting without backend dependencies."}, {"id": "R12", "priority": "SHOULD", "text": "The build process SHOULD provide clear error reporting for invalid Markdown, unresolvable internal links, or tag parsing failures, including file paths and line/position where applicable.", "rationale": "Improves maintainability and reduces friction when scaling to large note corpora."}, {"id": "R13", "priority": "MUST", "text": "The generated site MUST function in modern browsers (Chrome, Firefox, Safari, Edge) with core features (navigation, search, tag browsing, backlinks) working without runtime errors.", "rationale": "Cross-browser functionality is an explicit success metric for the generated static site."}, {"id": "R14", "priority": "SHOULD", "text": "The system SHOULD support configuration of the Markdown flavor, internal link syntax, and tag conventions used for parsing and site generation.", "rationale": "Key conventions are open questions; configurability helps avoid overpromising universal compatibility while allowing explicit selection."}, {"id": "R15", "priority": "SHOULD", "text": "The system SHOULD support CommonMark as a baseline Markdown flavor and SHOULD additionally support GitHub-Flavored Markdown (GFM) extensions such as tables, task lists, and strikethrough, with the exact flavor finalized based on the project’s selected conventions.", "rationale": "Establishes a concrete baseline for Markdown processing while allowing finalization per the project’s link/flavor decisions."}, {"id": "R16", "priority": "SHOULD", "text": "The system SHOULD support wiki-link style inter-note links (e.g., [[Note Title]]) in addition to standard Markdown links, with the exact syntax finalized based on the project’s chosen link convention.", "rationale": "Wiki-links are common in note-taking tools and broaden compatibility, but exact syntax is an open question."}, {"id": "R17", "priority": "SHOULD", "text": "The system SHOULD include a site-wide navigation structure with at minimum (a) an index/home page listing all notes and (b) a tag index page listing all tags.", "rationale": "Improves discoverability and makes the generated site easier to browse."}, {"id": "R18", "priority": "SHOULD", "text": "The system SHOULD support extracting tags from both YAML frontmatter and inline #tag syntax, with an option to configure which sources are used, aligned with the project’s selected tag convention.", "rationale": "Supports compatibility with different tagging styles; details depend on the project’s tag representation decision."}, {"id": "R19", "priority": "MUST", "text": "Search results MUST meet the defined search quality target: at least 90% of predefined representative queries return the expected note within the top 10 results.", "rationale": "Codifies the stated search success metric as a verifiable requirement."}, {"id": "R20", "priority": "MUST", "text": "Tag navigation MUST be complete: 100% of notes containing tags in the dataset MUST appear under their corresponding tag pages or filters in the generated site.", "rationale": "Codifies the tag correctness success metric as a verifiable requirement."}, {"id": "R21", "priority": "MUST", "text": "Backlink rendering MUST be correct: for a test set of interlinked notes, 100% of expected backlinks MUST appear on their target note pages.", "rationale": "Codifies the backlink correctness success metric as a verifiable requirement."}, {"id": "R22", "priority": "MUST", "text": "The build process MUST complete without errors on a representative notes folder and produce a valid set of static files.", "rationale": "Codifies the baseline build success metric required before other features can be evaluated."}, {"id": "R23", "priority": "SHOULD", "text": "On a representative dataset of 100+ notes, the system SHOULD meet agreed performance targets for generation time and in-browser search responsiveness; these targets SHOULD be defined/documented based on expected scale (e.g., search results within 500ms).", "rationale": "Performance requirements depend on scale, which is not yet fully specified; this ensures explicit targets and validation."}, {"id": "R24", "priority": "SHOULD", "text": "The system SHOULD generate a table of contents (outline) for each note page based on its heading structure.", "rationale": "Improves within-note navigation, especially for long notes."}, {"id": "R25", "priority": "SHOULD", "text": "The CLI SHOULD provide a watch mode that monitors the input directory for changes and incrementally regenerates affected pages.", "rationale": "Improves the authoring workflow during active note editing and site preview."}, {"id": "R26", "priority": "COULD", "text": "The generated site COULD include an interactive graph view visualizing link relationships between notes.", "rationale": "Optional discovery feature; not required for core generation, tags, search, and backlinks."}, {"id": "R27", "priority": "COULD", "text": "The system COULD support theming or customizable styling of the generated site via user-provided CSS or theme configuration.", "rationale": "Optional customization feature; not required for core functionality."}, {"id": "R28", "priority": "COULD", "text": "Search COULD support advanced features such as fuzzy matching, tag-based filtering, result highlighting, and sorting by relevance.", "rationale": "Optional enhancements to search experience beyond basic full-text search."}, {"id": "R29", "priority": "COULD", "text": "The system COULD support nested/hierarchical tags (e.g., #parent/child) and reflect the hierarchy in tag navigation.", "rationale": "Optional capability for complex tag taxonomies; not required for baseline tag browsing."}], "acceptance_tests": [{"id": "AT1", "maps_to_requirements": ["R1"], "type": "system", "procedure": "Create a test input directory with nested subfolders containing .md files and non-.md files. Run the CLI build specifying the root input directory and an output directory. Inspect the discovered notes list (build log or generated site pages) to confirm recursive discovery.", "pass_criteria": "All .md files in all subfolders are included as notes; non-.md files are excluded."}, {"id": "AT2", "maps_to_requirements": ["R2"], "type": "system", "procedure": "Run the build on a representative notes folder. Inspect the output directory contents and attempt to open the site via a local static file server (or static hosting).", "pass_criteria": "Build completes successfully; output contains only static assets (HTML/CSS/JS/media); site functions without any server-side runtime for browsing, search, tags, or backlinks."}, {"id": "AT3", "maps_to_requirements": ["R3"], "type": "human_eval", "procedure": "Prepare notes covering headings, lists, code blocks, blockquotes, links, images, and tables per the selected Markdown flavor. Build the site and visually compare rendered HTML output to expected formatting.", "pass_criteria": "All tested Markdown elements render correctly and preserve structure and formatting."}, {"id": "AT4", "maps_to_requirements": ["R4"], "type": "system", "procedure": "Create notes with known filenames/paths and optional frontmatter slugs. Build the site and record the generated URLs for each note. Rebuild without changes and compare URLs.", "pass_criteria": "Each note has a distinct page; URLs are deterministically derived from path/filename or frontmatter slug and remain stable across rebuilds."}, {"id": "AT5", "maps_to_requirements": ["R5"], "type": "system", "procedure": "Build the site and verify that a search index artifact is generated. Open the site in a browser with network disabled and perform searches via the UI.", "pass_criteria": "Search operates fully client-side without network access; search returns results across note contents/titles."}, {"id": "AT6", "maps_to_requirements": ["R7", "R20"], "type": "system", "procedure": "Create a dataset with tagged and untagged notes using the specified tag convention. Build the site and navigate tag pages/filters. Count notes per tag and compare with source data.", "pass_criteria": "All tagged notes appear under each corresponding tag; untagged notes are not listed; 100% of notes with tags are included under the correct tag pages/filters."}, {"id": "AT7", "maps_to_requirements": ["R8"], "type": "system", "procedure": "Build a dataset with multiple tags across notes. Build the site and navigate to each tag’s listing page or filter UI.", "pass_criteria": "Each tag has a navigable listing showing all notes containing that tag, with working links to note pages."}, {"id": "AT8", "maps_to_requirements": ["R9"], "type": "system", "procedure": "Create notes with internal forward links using the specified link syntax. Build the site and click each internal link in rendered pages.", "pass_criteria": "All internal links resolve to the correct target note pages and are rendered as clickable elements."}, {"id": "AT9", "maps_to_requirements": ["R10", "R21"], "type": "system", "procedure": "Create a known link graph (e.g., A→B, C→B, B→D). Build the site and inspect backlinks sections on each note page.", "pass_criteria": "Each note’s backlinks list includes all and only notes that link to it; for the test set, 100% of expected backlinks appear."}, {"id": "AT10", "maps_to_requirements": ["R11"], "type": "system", "procedure": "Run the CLI build specifying input and output directories while offline (no network).", "pass_criteria": "CLI accepts input/output paths; build completes without network access and produces the static site output."}, {"id": "AT11", "maps_to_requirements": ["R13"], "type": "human_eval", "procedure": "Open the generated site in latest Chrome, Firefox, Safari, and Edge. Test navigation, search, tag browsing, and backlinks in each browser.", "pass_criteria": "Core features function without runtime errors in all listed browsers."}, {"id": "AT12", "maps_to_requirements": ["R19"], "type": "metric", "procedure": "Define a representative query set with expected target notes. Build the site and execute each query in the search UI, recording the top 10 results.", "pass_criteria": "At least 90% of queries return the expected note within the top 10 results."}, {"id": "AT13", "maps_to_requirements": ["R22"], "type": "system", "procedure": "Run the build on a representative notes folder and monitor for errors. Verify output directory contains generated static files.", "pass_criteria": "Build completes without errors and produces a valid set of static files."}], "architecture": {"options": [{"id": "O1", "summary": "Monolithic single-command CLI that runs an in-memory build pipeline end-to-end: read Markdown notes, extract metadata/tags/links, compute backlinks, build a client-side search index, and render a complete static HTML/CSS/JS site in one execution.", "components": [{"id": "C1", "name": "CLI Entry Point / Orchestrator", "responsibilities": ["Parse command-line arguments (input folder, output folder, config file path)", "Orchestrate the build pipeline stages in sequence in a single run", "Report build progress and errors to stdout/stderr"]}, {"id": "C2", "name": "Markdown Parser & Metadata Extractor", "responsibilities": ["Read all .md files from the input directory tree", "Parse YAML frontmatter to extract tags and metadata", "Parse Markdown into an AST and/or HTML-ready representation", "Detect and normalize internal links (standard Markdown links and optional wiki-links)"]}, {"id": "C3", "name": "Graph (Links/Backlinks) Engine", "responsibilities": ["Build a forward-link graph from parsed internal links", "Compute backlinks for every note from the inverse graph", "Resolve link targets to output URLs", "Report broken/unresolvable links as warnings"]}, {"id": "C4", "name": "Tag Index Builder", "responsibilities": ["Aggregate tags across all notes", "Generate per-tag note lists", "Produce a tag index structure for tag browsing pages"]}, {"id": "C5", "name": "Search Index Generator", "responsibilities": ["Build a client-side full-text search index from note titles/content/tags at build time", "Serialize the index to a JSON (or equivalent) file included in the static output", "Apply basic index-size controls (e.g., stemming/stop words) as needed"]}, {"id": "C6", "name": "HTML Renderer / Templating", "responsibilities": ["Convert Markdown/AST to HTML", "Inject backlinks, tag lists, and navigation into page templates", "Render tag index pages, home page, and search page", "Copy static assets (CSS, JS, images) to the output directory"]}, {"id": "C7", "name": "Client-Side Search UI", "responsibilities": ["Load the pre-built search index in the browser", "Provide a search input with results rendering", "Optionally highlight matched terms in result snippets"]}], "interfaces": [{"id": "IF1", "from": "C1", "to": "C2", "contract": "Pass input directory path and config (Markdown flavor, link/tag syntax options) to the parser/extractor."}, {"id": "IF2", "from": "C2", "to": "C3", "contract": "Emit in-memory note records including slugs/titles/metadata and extracted forward links for link graph + backlink computation."}, {"id": "IF3", "from": "C2", "to": "C4", "contract": "Provide extracted tags per note (from frontmatter and/or inline tag syntax) for aggregation and tag page generation."}, {"id": "IF4", "from": "C2", "to": "C5", "contract": "Provide per-note indexable fields (slug, title, plain text content, tags) to build the search index artifact."}, {"id": "IF5", "from": "C3", "to": "C6", "contract": "Provide backlinks per note (e.g., Map<slug, BacklinkEntry[]>) for rendering on note pages."}, {"id": "IF6", "from": "C4", "to": "C6", "contract": "Provide tag index (e.g., Map<tag, slug[]>) for rendering tag pages and per-note tag navigation."}, {"id": "IF7", "from": "C5", "to": "C6", "contract": "Output a serialized search index file into the output assets and return its relative path for inclusion in the rendered site."}, {"id": "IF8", "from": "C6", "to": "C7", "contract": "Rendered search page references the search index asset and client-side JS bundle via static <script>/<link> tags."}], "tradeoffs": {"pros": ["Simple single-process build; easy to reason about and debug", "Simple user experience: one command generates the whole site", "Potentially fast for small-to-medium note sets due to in-memory stage handoff", "Straightforward deployment: run CLI, upload output folder"], "cons": ["Monolithic codebase can become harder to extend (themes, graph view, alternative search backends)", "Less flexibility to swap individual parts without code changes", "Often implies full rebuild on any change unless incremental build is explicitly implemented", "Client-side search index size can grow and impact first-load performance for large note sets"]}, "risks": ["Search index asset may become too large for very large note sets, degrading initial load time", "Memory usage can grow substantially at very large scale (e.g., many thousands of notes) due to in-memory representations", "Wiki-link and tag syntax ambiguity can cause incorrect extraction/resolution without a clear specification", "Single-threaded sequential build may become slow on very large repositories"]}, {"id": "O2", "summary": "Custom plugin-based static site generator core with a formal build lifecycle and plugin API; each concern (file collection, Markdown parsing, backlinks, tags, search, theming) is a plugin, enabling swapping/extending behavior without modifying the core.", "components": [{"id": "C8", "name": "Core Orchestrator & Plugin Host", "responsibilities": ["Load configuration and discover/register plugins", "Define and execute build lifecycle hooks (init, collectFiles, transform, resolve, render, finalize)", "Manage shared build context (note registry, site metadata, output paths)"]}, {"id": "C9", "name": "File Collector Plugin", "responsibilities": ["Recursively scan input directory for Markdown files", "Emit file metadata into the shared note registry", "Support configurable file include/exclude patterns"]}, {"id": "C10", "name": "Markdown Parser Plugin", "responsibilities": ["Parse each Markdown file into an AST (or equivalent)", "Extract YAML frontmatter", "Normalize internal link references into a canonical format"]}, {"id": "C11", "name": "Backlink Resolver Plugin", "responsibilities": ["Build forward-link and backlink graphs from parsed link data", "Attach backlink metadata to each note in the shared registry"]}, {"id": "C12", "name": "Tag Aggregator Plugin", "responsibilities": ["Collect tags from frontmatter and/or inline tag syntax", "Build tag-to-notes index", "Register tag index pages for rendering"]}, {"id": "C13", "name": "Search Index Plugin", "responsibilities": ["Build a client-side search index and write index artifacts to the output directory", "Optionally support chunked/sharded index artifacts for larger sites"]}, {"id": "C14", "name": "Theme / Renderer Plugin", "responsibilities": ["Provide HTML templates and CSS/JS assets", "Render note pages and index/tag/search pages using the shared build context", "Support theme switching via configuration"]}, {"id": "C15", "name": "Client-Side Runtime", "responsibilities": ["Load and query the generated search index assets in the browser", "Render interactive search results and navigation UI elements", "Provide tag filter UI and backlink navigation"]}], "interfaces": [{"id": "IF9", "from": "C8", "to": "C9", "contract": "Hook: collectFiles(context) → context.noteRegistry populated with entries (filePath, slug)."}, {"id": "IF10", "from": "C8", "to": "C10", "contract": "Hook: transform(context) → each note enriched with (ast, frontmatter, rawLinks[])."}, {"id": "IF11", "from": "C8", "to": "C11", "contract": "Hook: resolve(context) → backlink map attached to context and/or notes."}, {"id": "IF12", "from": "C8", "to": "C12", "contract": "Hook: resolve(context) → tag index attached to context and tag pages registered for render."}, {"id": "IF13", "from": "C8", "to": "C13", "contract": "Hook: finalize(context) → search index artifacts written to output directory (optionally sharded)."}, {"id": "IF14", "from": "C8", "to": "C14", "contract": "Hook: render(context) → HTML files and static theme assets written to output directory using context data."}, {"id": "IF15", "from": "C14", "to": "C15", "contract": "Rendered pages reference client-side JS bundle and search index assets via relative static paths."}], "tradeoffs": {"pros": ["Highly extensible: new features can be added as plugins without changing the core", "Clean separation of concerns, improving testability and maintainability", "Themes and search backends can be swapped via plugin selection/configuration", "Can evolve toward large-site needs (e.g., sharded search indexes) within a consistent lifecycle"], "cons": ["More upfront design and implementation effort (plugin API, hook semantics, shared context schema)", "Plugin ordering and inter-plugin dependencies add complexity", "Debugging cross-plugin issues can be harder than a monolith", "Over-engineering risk for a small-scope initial release"]}, "risks": ["Plugin API may need multiple iterations to stabilize, delaying initial delivery", "Poorly specified plugin contracts can lead to brittle plugins and breaking changes", "Performance overhead or complexity from hook dispatch and large shared context objects may emerge at scale"]}, {"id": "O3", "summary": "Use an existing static site generator (SSG), specifically Eleventy/11ty, as the build engine; implement backlinks, tags, and search as Eleventy plugins/config, leveraging its templating, collections/data model, and watch/incremental build capabilities (with Pagefind for scalable client-side search).", "components": [{"id": "C16", "name": "Eleventy (11ty) Core Engine", "responsibilities": ["Handle file discovery, templating, and static output generation", "Provide data cascade and collections APIs for structured content data", "Support watch mode and incremental rebuilds"]}, {"id": "C17", "name": "Markdown Processing Configuration", "responsibilities": ["Configure Markdown library/flavor and parsing options", "Add wiki-link syntax support via Markdown plugin (if required)", "Extract frontmatter into Eleventy’s data model"]}, {"id": "C18", "name": "Backlink Data Plugin (Eleventy Plugin)", "responsibilities": ["Scan collections/content for internal links", "Compute backlinks and inject backlink data into each note’s template data"]}, {"id": "C19", "name": "Tag Collections & Tag Pages", "responsibilities": ["Use Eleventy’s tags/collections mechanisms to aggregate tags", "Generate per-tag index pages (e.g., via pagination templates)", "Provide tag lists/tag cloud data to templates"]}, {"id": "C20", "name": "Search Index Build Step (Pagefind or equivalent)", "responsibilities": ["Generate a client-side full-text search index during/after the Eleventy build", "Index the rendered HTML output for accurate search over final content", "Write search assets into the output directory"]}, {"id": "C21", "name": "Theme / Layout Templates", "responsibilities": ["Provide templates for note pages, tag pages, home, and search", "Include CSS and any client-side JS needed for navigation/backlinks/search integration", "Render backlink sections and tag links within templates"]}, {"id": "C22", "name": "Client-Side Search UI (Pagefind UI or custom)", "responsibilities": ["Load chunked search index assets on demand", "Provide interactive search UI with highlighting", "Operate entirely client-side in the static site"]}], "interfaces": [{"id": "IF16", "from": "C16", "to": "C17", "contract": "Eleventy config registers Markdown processing (including wiki-link plugin if needed); .md files are processed through this configuration."}, {"id": "IF17", "from": "C16", "to": "C18", "contract": "Eleventy plugin hook/collection step receives all notes/collection items and can compute backlinks to inject into template data."}, {"id": "IF18", "from": "C18", "to": "C21", "contract": "Each note’s data object includes backlinks[] (e.g., {slug, title, excerpt/context}) available to templates."}, {"id": "IF19", "from": "C16", "to": "C19", "contract": "Tags/collections are populated from frontmatter tags (and/or derived tags) and made available to templates and pagination."}, {"id": "IF20", "from": "C16", "to": "C20", "contract": "AfterBuild (or equivalent) triggers search indexing against the built output directory."}, {"id": "IF21", "from": "C20", "to": "C22", "contract": "Search build step outputs static (often chunked) search assets; the search page includes references to these assets and UI JS."}, {"id": "IF22", "from": "C21", "to": "C16", "contract": "Templates are registered/configured in Eleventy and used to produce final static output files."}], "tradeoffs": {"pros": ["Reduces custom code by leveraging a mature SSG for file handling and templating", "Watch mode and incremental builds available out of the box", "Pagefind-style search produces chunked indexes that scale better to thousands of pages", "Access to ecosystem of plugins/themes and community support"], "cons": ["Constrained by the chosen SSG’s conventions, APIs, and upgrade cycle", "Backlink computation still requires custom integration with the SSG data model", "Less control over build pipeline internals than a fully custom generator", "Additional dependencies (SSG + plugins), and potentially a non-JS binary for search indexing"]}, "risks": ["SSG plugin/data model limitations may force workarounds for specific features", "Upgrades to the SSG or plugin APIs may introduce breaking changes requiring maintenance", "Search indexing toolchain (e.g., Pagefind) may add CI/CD complexity on some platforms", "Wiki-link resolution plugin may not cover all desired dialects/edge cases without customization"]}, {"id": "O4", "summary": "Composable multi-tool pipeline: separate single-responsibility CLI tools (parser, backlink enricher, search indexer, renderer) communicate via intermediate on-disk artifacts (e.g., JSON), allowing independent development and replacement of stages while still producing a static site output.", "components": [{"id": "C23", "name": "Content Parser (CLI)", "responsibilities": ["Scan a directory of Markdown files", "Output a structured data file (e.g., notes.json) containing content, metadata, tags, and extracted forward links for every note"]}, {"id": "C24", "name": "Data Enricher (Backlinks) (CLI)", "responsibilities": ["Consume structured notes data from the parser", "Analyze the link graph to compute backlinks for each note", "Output an enriched structured data file including backlink information"]}, {"id": "C25", "name": "Search Indexer (CLI)", "responsibilities": ["Consume structured notes data from the parser (or enriched data if desired)", "Generate a static client-side search index artifact (e.g., JSON files)"]}, {"id": "C26", "name": "Site Renderer (CLI)", "responsibilities": ["Consume enriched structured data to generate final HTML pages using templates", "Copy generated pages, search index artifacts, and other static assets to the output directory"]}], "interfaces": [{"id": "IF23", "from": "C23", "to": "C24", "contract": "On-disk structured data file (e.g., notes.json) containing parsed note content/metadata and extracted forward links."}, {"id": "IF24", "from": "C23", "to": "C25", "contract": "On-disk structured data file (e.g., notes.json) containing parsed note content/metadata and extracted forward links."}, {"id": "IF25", "from": "C24", "to": "C26", "contract": "On-disk enriched data file (e.g., enriched-notes.json) containing backlink information per note."}, {"id": "IF26", "from": "C25", "to": "C26", "contract": "On-disk search index artifact(s) (e.g., search-index.json and related files) to be copied/embedded into the final site output."}], "tradeoffs": {"pros": ["High modularity: each stage can be developed, tested, and replaced independently", "Easier to mix technologies across stages (e.g., parser in one language, renderer in another)", "Clear intermediate artifact(s) can aid debugging and reproducibility"], "cons": ["More complex build orchestration for the end-user compared to a single command", "I/O overhead from writing/reading intermediate files can reduce performance", "Intermediate schema/versioning must be maintained carefully across tools"]}, "risks": ["User experience may suffer if orchestration is cumbersome (multiple commands, ordering, cleanup)", "Intermediate JSON/schema changes require coordinated updates across multiple tools", "Disk usage can increase due to large intermediate artifacts on big note sets"]}], "chosen": {"option_id": "O2", "rationale": "O2's plugin-based architecture directly addresses the project's long-term extensibility goals. Each concern—file collection, Markdown parsing, backlink resolution, tag aggregation, search indexing, and rendering—is encapsulated as a plugin with a well-defined lifecycle hook contract managed by the Core Orchestrator (C8). This yields superior testability (each plugin can be tested in isolation by mocking the shared build context), maintainability (changes to one feature do not ripple through unrelated code), and adaptability (future features like graph views, themes, or alternative search backends can be added as new plugins). The primary trade-off is higher upfront design effort for the plugin API and shared context schema, which is mitigated by dedicating the entire first milestone to stabilizing these foundations. Compared to O1 (monolith), O2 avoids the coupling that makes monoliths hard to extend. Compared to O3 (Eleventy-based), O2 avoids dependency on a third-party SSG's conventions and upgrade cycle. Compared to O4 (multi-tool pipeline), O2 keeps the single-process developer experience while achieving comparable modularity.", "high_level_dataflow": "CLI invocation → Core Orchestrator (C8) loads config and registers plugins → init hook → File Collector Plugin (C9) populates noteRegistry in shared context via collectFiles hook → Markdown Parser Plugin (C10) enriches each note with AST, frontmatter, and raw links via transform hook → Backlink Resolver Plugin (C11) builds forward/backlink graphs and attaches backlink metadata via resolve hook → Tag Aggregator Plugin (C12) builds tag index and registers tag pages via resolve hook → Theme/Renderer Plugin (C14) renders note pages, tag pages, index, and search page to output directory via render hook → Search Index Plugin (C13) builds and writes client-side search index artifacts via finalize hook → Client-Side Runtime (C15) loads search index and provides interactive search/tag/backlink UI in the browser.", "key_design_decisions": ["DEC1", "DEC2", "DEC3", "DEC4", "DEC5", "DEC6"]}}, "milestones": [{"id": "M1", "name": "Core Foundation (Big Bang)", "deliverables": [{"id": "DL1", "text": "Core Orchestrator (C8) with build lifecycle hooks (init, collectFiles, transform, resolve, render, finalize) and plugin registration/discovery mechanism."}, {"id": "DL2", "text": "Shared build context schema definition (noteRegistry, site metadata, output paths) with TypeScript types or JSON Schema."}, {"id": "DL3", "text": "Plugin API contract documentation specifying hook signatures, execution order, and inter-plugin dependency declaration."}, {"id": "DL4", "text": "File Collector Plugin (C9) that recursively discovers .md files and populates the noteRegistry."}, {"id": "DL5", "text": "Markdown Parser Plugin (C10) that parses Markdown to AST, extracts frontmatter, and normalizes internal link references."}, {"id": "DL6", "text": "CLI entry point accepting input directory, output directory, and config file path (R11)."}, {"id": "DL7", "text": "Unit and integration tests for the orchestrator lifecycle, plugin loading, and the two foundation plugins."}], "exit_criteria": ["Core Orchestrator executes all lifecycle hooks in the correct order with registered plugins.", "File Collector Plugin discovers all .md files recursively and excludes non-.md files (AT1 partial).", "Markdown Parser Plugin produces correct AST and extracts frontmatter for representative Markdown files.", "Plugin API contract is documented and reviewed.", "Shared context schema is defined, versioned, and validated at runtime.", "CLI accepts input/output paths and invokes the build pipeline (AT10 partial)."], "depends_on": []}, {"id": "M2", "name": "Feature Plugins (Thin Slice)", "deliverables": [{"id": "DL8", "text": "Backlink Resolver Plugin (C11) computing forward-link and backlink graphs from parsed link data and attaching backlink metadata to each note."}, {"id": "DL9", "text": "Tag Aggregator Plugin (C12) collecting tags from frontmatter and/or inline syntax, building tag-to-notes index, and registering tag pages."}, {"id": "DL10", "text": "Search Index Plugin (C13) building a client-side full-text search index artifact and writing it to the output directory."}, {"id": "DL11", "text": "Theme/Renderer Plugin (C14) rendering note pages, tag pages, index/home page, and search page to static HTML/CSS/JS output."}, {"id": "DL12", "text": "Client-Side Runtime (C15) providing in-browser search UI, tag filter navigation, and backlink display."}, {"id": "DL13", "text": "Per-plugin isolation tests using mocked build context, plus integration tests for plugin ordering and inter-plugin data flow."}], "exit_criteria": ["Backlinks are correctly computed for a known link graph (AT9 pass criteria met).", "100% of tagged notes appear under correct tag pages (AT6 pass criteria met).", "Client-side search operates without network access and returns results across note contents (AT5 pass criteria met).", "Each note has a distinct page with a stable, deterministic URL (AT4 pass criteria met).", "Forward links resolve to correct target pages (AT8 pass criteria met).", "Generated output consists only of static files (AT2 pass criteria met).", "Blocking questions Q1 and Q2 are resolved before plugin implementation begins."], "depends_on": ["M1"]}, {"id": "M3", "name": "Integration, Hardening & Acceptance", "deliverables": [{"id": "DL14", "text": "End-to-end acceptance test suite covering AT1–AT13 with a representative 100+ note dataset."}, {"id": "DL15", "text": "Cross-browser validation report for Chrome, Firefox, Safari, and Edge (AT11)."}, {"id": "DL16", "text": "Search quality benchmark confirming ≥90% of representative queries return expected note in top 10 (AT12)."}, {"id": "DL17", "text": "Performance benchmark for build time and in-browser search responsiveness on 100+ note dataset (R23)."}, {"id": "DL18", "text": "Security hardening: XSS payload test suite, raw HTML sanitization, unsafe URL scheme blocking (K3 mitigation)."}, {"id": "DL19", "text": "Build determinism verification: two clean builds produce identical output (K6 mitigation)."}, {"id": "DL20", "text": "Error reporting for invalid Markdown, unresolvable links, and tag parsing failures with file paths (R12)."}, {"id": "DL21", "text": "Documentation: README, CLI usage guide, plugin authoring guide, and configuration reference."}], "exit_criteria": ["All acceptance tests AT1–AT13 pass.", "Cross-browser testing passes without runtime errors in all target browsers (AT11).", "Search quality target met: ≥90% of queries return expected note in top 10 (AT12).", "Build completes without errors on representative dataset (AT13).", "No critical or high-severity security findings remain unmitigated.", "Build determinism check passes (two identical outputs from clean runs).", "Performance targets documented and met for 100+ note dataset."], "depends_on": ["M2"]}], "risk_register": [{"id": "K1", "severity": "high", "description": "Link/backlink resolution errors due to ambiguous or mixed internal link syntax (e.g., Markdown links vs. WikiLinks), causing broken navigation and incorrect backlink lists (blocking Q1).", "mitigation": {"text": "Resolve and document the supported internal link syntax (Q1). Implement a single canonical internal link model (normalized target IDs) with deterministic resolution rules. Add fixture-based tests for edge cases (relative paths, anchors, URL-encoding, renamed files). Emit build warnings for unresolved links including source locations.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K2", "severity": "high", "description": "Tag extraction inconsistency due to unspecified or mixed tag formats (frontmatter vs inline tags; nested tags), leading to missing/incorrect tag pages and filtering (blocking Q2).", "mitigation": {"text": "Resolve and document the tag specification (Q2). Implement a deterministic tag parser with explicit precedence rules and validation (report invalid tokens). Produce a build-time summary/tag inventory and add tests for the chosen formats (frontmatter, inline, optional nested).", "owner": "Product/Engineering", "status": "planned"}, "acceptance": null}, {"id": "K3", "severity": "critical", "description": "Client-side XSS or content injection vulnerabilities if Markdown/HTML is rendered unsafely (e.g., raw HTML passthrough, unsafe link protocols), compromising readers of the static site.", "mitigation": {"text": "Disable raw HTML by default (or sanitize it) in the renderer; block unsafe URL schemes (e.g., javascript:) and enforce safe attributes. Add security tests with known XSS payloads. If allowing trusted raw HTML, require explicit opt-in configuration and document the risk.", "owner": "Security/Engineering", "status": "planned"}, "acceptance": null}, {"id": "K4", "severity": "high", "description": "Client-side search index size/quality/performance may degrade at scale (large JS payload, slow queries, long build time), causing poor UX or crashes (related to Q3/SM7).", "mitigation": {"text": "Define expected scale and performance targets (Q3). Choose an index approach suitable for in-browser search; apply index-size controls (tokenization choices, compression, lazy loading/chunking where applicable). Add benchmark fixtures and CI performance budgets; validate search quality targets against representative queries.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K5", "severity": "medium", "description": "Slug/URL collisions (e.g., same filename in different folders, case-insensitive filesystems) cause pages to overwrite each other or links to resolve unpredictably.", "mitigation": {"text": "Define a deterministic slug strategy (include path segments and/or stable hashing). Detect collisions during build and fail with actionable errors unless an explicit override map is provided.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K6", "severity": "high", "description": "Non-deterministic builds (ordering differences, locale/time-dependent formatting, unpinned dependencies) produce noisy diffs and inconsistent site output across machines/CI.", "mitigation": {"text": "Enforce determinism: stable sorting of inputs, fixed locale/timezone handling, content-hash-based asset naming, and pinned dependency versions/lockfiles. Add a reproducibility check comparing outputs across two clean runs.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K7", "severity": "high", "description": "Markdown flavor/extension mismatch or unsupported/non-standard syntax yields rendering differences, broken formatting, or build failures relative to user expectations.", "mitigation": {"text": "Select and document a supported Markdown flavor and extensions (e.g., CommonMark baseline with explicit GFM extensions if supported). Add a conformance test pack with representative notes, robust error handling, and a strict mode that flags unsupported syntax.", "owner": "Product/Engineering", "status": "planned"}, "acceptance": null}, {"id": "K8", "severity": "medium", "description": "File encoding and Unicode handling issues (non-UTF8, BOM, mixed line endings) cause build failures or corrupted output text/search results.", "mitigation": {"text": "Assume UTF-8 by default but detect/handle BOM and common encodings where feasible. Normalize line endings internally. Emit clear diagnostics identifying offending files and provide a preflight validation command.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K9", "severity": "high", "description": "Path traversal or unintended file inclusion during ingestion (e.g., following symlinks, reading outside the intended directory) could leak local files into the generated site.", "mitigation": {"text": "Constrain ingestion to a declared root directory; default to not following symlinks; maintain an allowlist of file extensions. Reject paths escaping the root and generate an inclusion manifest for review.", "owner": "Security/Engineering", "status": "planned"}, "acceptance": null}, {"id": "K10", "severity": "medium", "description": "Backlink computation gaps for links with anchors, URL-encoded paths, or inconsistent normalization lead to partially missing backlink lists.", "mitigation": {"text": "Normalize link targets consistently (decode, resolve relative paths, standardize/strip anchors where appropriate) and test anchor links and encoded characters. Ensure link resolution uses the same canonicalization used for URL/slug generation.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K11", "severity": "medium", "description": "Broken offline/local viewing when opened via file:// due to browser restrictions (e.g., fetch/XHR blocked), especially impacting search and other JS features.", "mitigation": {"text": "Design search/runtime to work on static hosts; for local preview, provide guidance to run a simple local server. Optionally embed the index into a JS bundle to avoid runtime fetch, or detect file:// and show instructions.", "owner": "Engineering/Docs", "status": "planned"}, "acceptance": null}, {"id": "K12", "severity": "medium", "description": "Asset/link path resolution issues (broken relative paths, missing CSS/JS, incorrect base URL) can cause the site to work locally but fail when deployed under a subpath (e.g., GitHub Pages), and/or break nested-directory links/images.", "mitigation": {"text": "Support configurable basePath and generate links/assets relative to it. Establish a clear rule for resolving relative paths for notes and assets in nested directories. Add deployment-mode tests (non-root basePath) and nested-content fixtures with link/asset checks over the output.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K13", "severity": "medium", "description": "Excessive memory usage or slow build times on large repositories (including inefficient backlink generation) can cause build failures/timeouts in CI or on user machines.", "mitigation": {"text": "Profile CPU/memory usage; stream where possible; avoid loading all contents at once; optimize link-graph/backlink computation; implement caching/incremental indexing where feasible. Provide configurable limits (max file size, exclude globs) and a performance troubleshooting guide.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K14", "severity": "high", "description": "Incorrect incremental rebuild/watch behavior (if implemented) can lead to stale search index/backlinks after edits, renames, or deletes, confusing users.", "mitigation": {"text": "If watch mode is offered, implement a dependency graph so edits trigger recomputation of affected pages, backlinks, and search index. Provide a 'full rebuild' fallback and add tests for edit/rename/delete scenarios.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K15", "severity": "medium", "description": "Cross-browser compatibility and accessibility issues in generated HTML/CSS/JS (including search UI) may lead to runtime errors or reduced usability for some readers (SM6).", "mitigation": {"text": "Define target browsers and test across them. Adopt baseline accessibility guidelines for templates/components (semantic HTML, focus management, ARIA where needed). Add at least one automated audit step (e.g., Lighthouse/axe) plus manual spot checks.", "owner": "Engineering/Design", "status": "planned"}, "acceptance": null}, {"id": "K16", "severity": "medium", "description": "Overly permissive configuration or plugin/theme extensibility (if added) can introduce instability and make outputs hard to support/reproduce.", "mitigation": {"text": "Keep configuration surface minimal initially; validate configuration schemas; version configurations; gate plugin execution behind explicit allowlists and warnings. Provide a safe default preset and a compatibility policy.", "owner": "Product/Engineering", "status": "planned"}, "acceptance": null}, {"id": "K17", "severity": "medium", "description": "Information disclosure via generated artifacts (e.g., including private notes, embedding absolute filesystem paths in HTML/JS/search index).", "mitigation": {"text": "Support exclude patterns (globs) and a 'private' frontmatter flag. Ensure generated output never includes absolute source paths (use relative identifiers only). Emit a build manifest listing included sources for review.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K18", "severity": "high", "description": "Poorly managed third-party dependencies (e.g., Markdown parser, search indexer/SSG plugins) may introduce breaking changes or security vulnerabilities that destabilize the tool.", "mitigation": {"text": "Pin dependency versions and use a lockfile. Establish a dependency update/vetting process including automated vulnerability scanning and regression testing before upgrades.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K19", "severity": "medium", "description": "A complex installation process or system-specific dependencies for the CLI tool can create a high barrier to entry for users.", "mitigation": {"text": "Target a simple installation path (e.g., a single package manager). Document prerequisites clearly; minimize system-specific dependencies; consider producing distributable bundles where feasible.", "owner": "Engineering", "status": "planned"}, "acceptance": null}, {"id": "K20", "severity": "low", "description": "Scope creep from undefined secondary features (e.g., graph views, themes) could divert resources from core goals and delay delivery.", "mitigation": {"text": "Prioritize core features for MVP; defer optional features until after MVP and track them as distinct work items with explicit approval before implementation.", "owner": "Product", "status": "planned"}, "acceptance": null}], "governance": {"failure_modes": [], "tool_policy": {"stage_policies": [{"stage": "Intake", "allowlisted_tools": ["artifact_read", "artifact_write"], "restrictions": [{"tool": "artifact_read", "rule": "provided_artifacts_only", "notes": "Read only the artifacts explicitly provided in inputs/artifact_refs; no external sources."}, {"tool": "artifact_write", "rule": "write_required_outputs_only", "allowed_artifacts": ["audit_spine", "intake_notes"], "notes": "Artifact writes limited to intake governance outputs for traceability."}, {"artifact_write": "canonical_allowed_only_for_declared_types", "notes": "Allow canonical audit-spine artifacts (run_manifest, event_log, stage_handoff)."}], "hitl_triggers": ["Blocking specification decisions are required but missing (Q1 internal link syntax; Q2 tag representation).", "Any request to expand scope beyond the static-site constraint."]}, {"stage": "Generate", "allowlisted_tools": ["artifact_read", "artifact_write"], "restrictions": [{"tool": "artifact_read", "rule": "provided_artifacts_only", "notes": "Do not use external web browsing or non-provided sources."}, {"tool": "artifact_write", "rule": "planning_only_no_execution_claims", "notes": "Drafting/planning only; do not execute code, access network, or claim runtime validation."}, {"tool": "artifact_write", "rule": "no_secrets_or_local_paths", "notes": "Do not include credentials/tokens or absolute filesystem paths in outputs."}], "hitl_triggers": ["Proposed solution requires server-side runtime for browsing/search/tags/backlinks (violates static constraint).", "Proposed Markdown rendering enables raw/unsanitized HTML or unsafe URL schemes without explicit mitigation."]}, {"stage": "Validate", "allowlisted_tools": ["artifact_read", "artifact_write"], "restrictions": [{"tool": "artifact_write", "rule": "validation_outputs_only", "allowed_artifacts": ["validation_notes", "risk_checks"], "notes": "Write only checklists/findings; do not introduce major scope changes during validation."}], "hitl_triggers": ["Security-sensitive findings (e.g., XSS risk) lack a concrete mitigation.", "Performance/scale targets remain undefined while performance-sensitive features are being committed."]}, {"stage": "Review", "allowlisted_tools": ["artifact_read", "artifact_write"], "restrictions": [{"tool": "artifact_write", "rule": "write_required_outputs_only", "allowed_artifacts": ["review_findings", "audit_spine"], "notes": "Review must be able to write findings and update the audit spine."}, {"tool": "artifact_write", "rule": "no_untracked_decisions", "notes": "Any decision affecting link/tag spec, security posture, or hosting assumptions must be logged in review_findings."}, {"artifact_write": "canonical_allowed_only_for_declared_types", "notes": "Allow findings-only canonical artifacts (review_findings.json)."}], "hitl_triggers": ["Any acceptance of high/critical risks without explicit signoff rationale.", "Any change to blocking questions (Q1/Q2) without stakeholder approval."]}, {"stage": "Judge", "allowlisted_tools": ["artifact_read", "artifact_write"], "restrictions": [{"tool": "artifact_write", "rule": "decision_record_only", "allowed_artifacts": ["governance_decision", "risk_acceptance_log"], "notes": "Record accept/mitigate decisions only; no new features introduced."}], "hitl_triggers": ["Any critical risk remains unmitigated.", "Unresolved blocking questions remain (Q1 or Q2)."]}, {"stage": "Freeze", "allowlisted_tools": ["artifact_read", "artifact_write"], "restrictions": [{"tool": "artifact_write", "rule": "freeze_outputs_only", "allowed_artifacts": ["frozen_risk_register", "frozen_tool_policy"], "notes": "Freeze produces locked governance artifacts; edits require a new run."}], "hitl_triggers": ["Any attempt to modify frozen artifacts without a formal change request."]}]}, "hitl_policy": {"when_to_interrupt": ["Blocking specification decisions are required (Q1 internal link syntax; Q2 tag representation) and are not provided.", "Any proposal that violates the static-site constraint (requires a server/database at runtime).", "Any security-sensitive behavior is proposed (raw HTML passthrough, unsanitized rendering, unsafe URL schemes) without an explicit mitigation and reviewer approval.", "Any high/critical risk is proposed for acceptance rather than mitigation, or is accepted without explicit signoff rationale.", "Any ingestion behavior could read outside the intended directory (symlinks/path traversal) without explicit user confirmation.", "On repeated failures to pass critical path test cases.", "Before making significant architectural changes or adding new major dependencies.", "When a generated solution deviates from the defined project capsule requirements.", "Upon detection of a high-severity security vulnerability in code or dependencies."], "approval_roles": ["Product Owner", "Product Manager", "Tech Lead", "Engineering Lead", "Security Reviewer", "Security Analyst"]}}, "decision_log": [{"id": "DEC1", "question": "Which architecture option should be selected?", "choice": "O2 – Custom plugin-based static site generator core", "rationale": "O2 provides the best balance of extensibility, testability, and long-term maintainability for a project expected to grow in complexity. The plugin architecture allows each concern to be developed, tested, and replaced independently. The upfront cost of designing the plugin API is mitigated by dedicating M1 entirely to the core foundation.", "alternatives_considered": ["O1 – Monolithic CLI: simpler initially but harder to extend and maintain as features grow.", "O3 – Eleventy-based: reduces custom code but constrains the project to Eleventy's conventions and upgrade cycle.", "O4 – Multi-tool pipeline: high modularity but poor single-command UX and I/O overhead from intermediate files."], "what_would_change_this_decision": ["If the project scope is confirmed to remain very small and unlikely to grow, O1 would be simpler.", "If time-to-market is the overriding priority and extensibility is not valued, O3 would deliver faster.", "If the team has deep Eleventy expertise, O3's ecosystem advantages would outweigh O2's flexibility."], "evidence_pointers": [{"artifact_ref": "architecture_canonical_v1", "entity_id": "O2", "json_pointer": "/options/1", "note": "O2 option definition with plugin-based architecture", "candidate_id": null, "artifact_id": null, "quote": null}, {"artifact_ref": "branch_set_v1", "entity_id": "B2", "json_pointer": "/branches/1", "note": "Branch B2 selects O2 for extensibility and architectural purity", "candidate_id": null, "artifact_id": null, "quote": null}]}, {"id": "DEC2", "question": "What milestone strategy should be used?", "choice": "Hybrid: Big Bang for core foundation (M1), then Thin Slice for feature plugins (M2), followed by integration hardening (M3).", "rationale": "The plugin API and shared context schema are tightly coupled and must be designed together (Big Bang). Once the core is stable, individual feature plugins can be developed and validated incrementally (Thin Slice), reducing integration risk. A final hardening milestone ensures end-to-end acceptance.", "alternatives_considered": ["Pure Big Bang: higher integration risk and delayed feedback.", "Pure Thin Slice: difficult to slice the core orchestrator and plugin API incrementally without rework."], "what_would_change_this_decision": ["If the plugin API design proves trivial, M1 could be split into thinner slices.", "If the team is very large, parallel plugin development within M2 could be formalized as separate sub-milestones."], "evidence_pointers": [{"artifact_ref": "branch_set_v1", "entity_id": "B2", "json_pointer": "/branches/1/milestone_strategy", "note": "Hybrid strategy specified by branch definition", "candidate_id": null, "artifact_id": null, "quote": "Build a solid foundation first. Milestone 1 (Big Bang): Design and build the core orchestrator, plugin API, and shared context schema."}]}, {"id": "DEC3", "question": "How should the plugin lifecycle hooks be ordered?", "choice": "Fixed ordering: init → collectFiles → transform → resolve → render → finalize. Plugins declare which hooks they participate in and may declare dependencies on other plugins.", "rationale": "A fixed hook ordering simplifies reasoning about data flow and avoids circular dependencies. Dependency declarations allow the orchestrator to validate plugin ordering at startup and fail fast on misconfiguration.", "alternatives_considered": ["Event-based pub/sub: more flexible but harder to debug ordering issues.", "Explicit DAG scheduling: powerful but over-engineered for the current plugin count."], "what_would_change_this_decision": ["If plugin count grows significantly (>15), a DAG-based scheduler may become necessary.", "If plugins need to emit data consumed by earlier hooks, a multi-pass approach would be needed."], "evidence_pointers": [{"artifact_ref": "architecture_canonical_v1", "entity_id": "C8", "json_pointer": "/options/1/components/0", "note": "Core Orchestrator responsibilities include lifecycle hook execution", "candidate_id": null, "artifact_id": null, "quote": "Define and execute build lifecycle hooks (init, collectFiles, transform, resolve, render, finalize)"}]}, {"id": "DEC4", "question": "How should blocking questions Q1 (link syntax) and Q2 (tag format) be handled?", "choice": "Require resolution of Q1 and Q2 before M2 plugin implementation begins. M1 core design will use abstract link/tag models that are syntax-agnostic; concrete parsing is deferred to M2 plugins.", "rationale": "The core orchestrator and shared context schema can be designed without committing to a specific link or tag syntax. However, the Backlink Resolver, Tag Aggregator, and Markdown Parser plugins cannot be finalized without these decisions. This approach avoids blocking M1 while ensuring M2 has the information it needs.", "alternatives_considered": ["Assume Obsidian-style WikiLinks and frontmatter tags as defaults: risks rework if the user wants different conventions.", "Support all formats from the start: increases complexity and testing burden."], "what_would_change_this_decision": ["If the user provides Q1/Q2 answers immediately, concrete parsing can be included in M1.", "If the user explicitly requests multi-format support, R14/R16/R18 configurability becomes a MUST."], "evidence_pointers": [{"artifact_ref": "capsule_canonical_v1", "entity_id": "Q1", "json_pointer": "/open_questions/0", "note": "Blocking question on internal link syntax", "candidate_id": null, "artifact_id": null, "quote": "What Markdown flavor and internal link syntax should be supported for links/backlinks?"}, {"artifact_ref": "capsule_canonical_v1", "entity_id": "Q2", "json_pointer": "/open_questions/1", "note": "Blocking question on tag representation", "candidate_id": null, "artifact_id": null, "quote": "How are tags represented in the notes (YAML frontmatter key, inline #tags, both)?"}]}, {"id": "DEC5", "question": "What governance posture should be applied?", "choice": "Sandboxed tooling with high HITL strictness, as specified by the branch definition.", "rationale": "The plugin-based architecture introduces more moving parts than a monolith, warranting stricter human oversight. Sandboxed tooling ensures plugins cannot access resources outside the declared input directory. High HITL strictness ensures security-sensitive decisions (K3, K9) and specification decisions (Q1, Q2) receive explicit human approval.", "alternatives_considered": ["Lower HITL strictness: faster iteration but higher risk of unreviewed security or specification issues.", "Full sandbox with no tool access: too restrictive for build-time file I/O."], "what_would_change_this_decision": ["If the project is purely personal/internal with no public readers, HITL strictness could be relaxed.", "If automated security scanning is comprehensive, some manual review triggers could be removed."], "evidence_pointers": [{"artifact_ref": "branch_set_v1", "entity_id": "B2", "json_pointer": "/branches/1/governance_posture", "note": "Branch specifies sandboxed tooling with high HITL strictness", "candidate_id": null, "artifact_id": null, "quote": null}, {"artifact_ref": "risk_gov_canonical_v1", "entity_id": "K3", "json_pointer": "/risk_register/2", "note": "Critical XSS risk requiring strict governance", "candidate_id": null, "artifact_id": null, "quote": null}]}, {"id": "DEC6", "question": "How should search index scalability be addressed?", "choice": "The Search Index Plugin (C13) will support optional chunked/sharded index artifacts. Initial implementation uses a single index file; sharding is activated via configuration when the note count exceeds a threshold.", "rationale": "A single index file is simpler and sufficient for small-to-medium datasets. The plugin architecture makes it straightforward to swap in a sharded implementation later without changing other plugins. This directly mitigates K4 (search index scale/performance).", "alternatives_considered": ["Always shard: adds unnecessary complexity for small sites.", "Use Pagefind as the search backend: excellent scalability but adds a non-JS binary dependency (conflicts with the custom-core philosophy of O2).", "Defer entirely: risks poor UX at scale without a clear upgrade path."], "what_would_change_this_decision": ["If Q3 reveals the expected scale is >5000 notes, sharding should be the default from the start.", "If Pagefind integration is acceptable as a plugin, it could replace the custom search index plugin entirely."], "evidence_pointers": [{"artifact_ref": "risk_gov_canonical_v1", "entity_id": "K4", "json_pointer": "/risk_register/3", "note": "High-severity risk on search index scale/performance", "candidate_id": null, "artifact_id": null, "quote": "Client-side search index size/quality/performance may degrade at scale"}, {"artifact_ref": "architecture_canonical_v1", "entity_id": "C13", "json_pointer": "/options/1/components/5", "note": "Search Index Plugin supports optional sharding", "candidate_id": null, "artifact_id": null, "quote": "Optionally support chunked/sharded index artifacts for larger sites"}]}], "supplemental_evaluations": [{"title": "Risk Posture Alignment", "notes": "This candidate accepts significant upfront implementation risk (designing a stable plugin API) in exchange for long-term maintainability and extensibility. Key risks addressed: K1 and K2 are mitigated by deferring concrete syntax parsing to M2 after Q1/Q2 resolution. K3 (XSS) is addressed in M3 with dedicated security hardening. K4 (search scale) is mitigated by the shardable Search Index Plugin. K13 (build performance) is mitigated by the plugin architecture allowing performance-critical components to be optimized or replaced independently. K16 (configuration/plugin instability) is mitigated by the high HITL strictness and explicit plugin allowlisting. The primary residual risk is that the plugin API may require iteration (O2 risk), which is why M1 is dedicated entirely to stabilizing it.", "evidence": [{"artifact_ref": "branch_set_v1", "entity_id": "B2", "json_pointer": "/branches/1/risk_posture", "note": "Branch risk posture accepts upfront implementation risk for long-term gains", "candidate_id": null, "artifact_id": null, "quote": "Accepts significant upfront implementation risk related to designing a stable and performant plugin API"}, {"artifact_ref": "risk_gov_canonical_v1", "entity_id": "K16", "json_pointer": "/risk_register/15", "note": "Plugin extensibility instability risk", "candidate_id": null, "artifact_id": null, "quote": null}]}, {"title": "Acceptance Strategy Alignment", "notes": "The acceptance strategy focuses on plugin API contract testing. Each plugin is tested in isolation by mocking the shared build context (covered in M1 DL7 and M2 DL13). The Core Orchestrator is tested for correct lifecycle hook ordering and inter-plugin dependency management (M1 exit criteria). Final acceptance requires an E2E test with all plugins enabled (M3 DL14, covering AT1–AT13). This aligns with the branch's acceptance_strategy specification.", "evidence": [{"artifact_ref": "branch_set_v1", "entity_id": "B2", "json_pointer": "/branches/1/acceptance_strategy", "note": "Branch acceptance strategy emphasizes plugin contract testing and E2E validation", "candidate_id": null, "artifact_id": null, "quote": "Each plugin must be tested in isolation by mocking the build context."}, {"artifact_ref": "acceptance_canonical_v1", "entity_id": "AT2", "json_pointer": "/acceptance_tests/1", "note": "AT2 validates static-only output", "candidate_id": null, "artifact_id": null, "quote": null}]}, {"title": "SHOULD/COULD Requirement Coverage", "notes": "SHOULD requirements R6, R12, R14, R15, R16, R17, R18, R23, R24, R25 are addressed as follows: R6 (search results UI) is part of C15 in M2. R12 (error reporting) is DL20 in M3. R14 (configurability) is inherent in the plugin architecture. R15 (CommonMark/GFM) and R16 (wiki-links) depend on Q1 resolution and are implemented in the Markdown Parser Plugin. R17 (site navigation) is part of the Theme/Renderer Plugin. R18 (tag source config) depends on Q2 and is implemented in the Tag Aggregator Plugin. R23 (performance) is DL17 in M3. R24 (TOC) can be added as a renderer feature or separate plugin. R25 (watch mode) is deferred post-M3 as it depends on incremental rebuild support (K14). COULD requirements R26 (graph view), R27 (theming), R28 (advanced search), R29 (nested tags) are deferred per K20 scope management.", "evidence": [{"artifact_ref": "requirements_canonical_v1", "entity_id": "R25", "json_pointer": "/requirements/24", "note": "Watch mode deferred due to incremental rebuild complexity (K14)", "candidate_id": null, "artifact_id": null, "quote": null}, {"artifact_ref": "risk_gov_canonical_v1", "entity_id": "K20", "json_pointer": "/risk_register/19", "note": "Scope creep risk managed by deferring COULD features", "candidate_id": null, "artifact_id": null, "quote": "Prioritize core features for MVP; defer optional features until after MVP"}]}], "synthesis_warnings": [{"id": "W1", "severity": "high", "summary": "Blocking questions Q1 (internal link syntax) and Q2 (tag representation) must be resolved before Milestone M2 can begin. Without these answers, the Backlink Resolver Plugin (C11), Tag Aggregator Plugin (C12), and concrete Markdown Parser Plugin (C10) link/tag extraction logic cannot be finalized.", "routing_target": "hitl_escalation", "evidence": [{"artifact_ref": "capsule_canonical_v1", "entity_id": "Q1", "json_pointer": "/open_questions/0", "note": "Blocking question on link syntax", "candidate_id": null, "artifact_id": null, "quote": "What Markdown flavor and internal link syntax should be supported?"}, {"artifact_ref": "capsule_canonical_v1", "entity_id": "Q2", "json_pointer": "/open_questions/1", "note": "Blocking question on tag format", "candidate_id": null, "artifact_id": null, "quote": "How are tags represented in the notes?"}]}, {"id": "W2", "severity": "medium", "summary": "Performance targets for R23 (build time and search responsiveness) depend on Q3 (expected scale), which remains unresolved. M3 exit criteria reference these targets; if Q3 is not answered, targets will need to be assumed based on the 100+ note representative dataset.", "routing_target": "hitl_escalation", "evidence": [{"artifact_ref": "capsule_canonical_v1", "entity_id": "Q3", "json_pointer": "/open_questions/2", "note": "Scale and performance targets not yet defined", "candidate_id": null, "artifact_id": null, "quote": "What is the expected scale (number of notes/total size) and performance targets?"}, {"artifact_ref": "requirements_canonical_v1", "entity_id": "R23", "json_pointer": "/requirements/22", "note": "Performance requirement depends on scale definition", "candidate_id": null, "artifact_id": null, "quote": null}]}, {"id": "W3", "severity": "medium", "summary": "The plugin API stability risk (O2 cons) may require iteration during M1, potentially extending the M1 timeline. If the API requires more than one major revision, M2 start will be delayed.", "routing_target": "review", "evidence": [{"artifact_ref": "architecture_canonical_v1", "entity_id": "O2", "json_pointer": "/options/1/risks/0", "note": "Plugin API may need multiple iterations to stabilize", "candidate_id": null, "artifact_id": null, "quote": "Plugin API may need multiple iterations to stabilize, delaying initial delivery"}]}], "appendix": {"glossary": [{"term": "Static site", "definition": "A website composed of pre-generated files (HTML/CSS/JS/assets) that can be served without server-side application logic."}, {"term": "Markdown", "definition": "A lightweight markup language used to format plain text documents."}, {"term": "Backlink", "definition": "A list of notes/pages that link to the current note/page, computed by analyzing links across the note set."}, {"term": "Tag", "definition": "A label associated with a no